"1,44 Megabyte reichen für ein paar Seiten Text oder ein kleines Bild. Ein heutiges Handyfoto passt oft nicht drauf.": "1.44 megabytes is enough for a few pages of text or a small picture. A photo from today's phones often doesn't fit.",
"1783 stiegen in Paris die ersten Menschen mit einem Heissluftballon auf. Vorher hatte man ein Schaf, eine Ente und einen Hahn als Testpassagiere geschickt.": "In 1783 the first people went up in a hot-air balloon in Paris. Before that, a sheep, a duck and a rooster were sent up as test passengers.",
"1947 fand man in einem Computer an der Harvard-Universität eine echte Motte, die einen Fehler verursacht hatte. Sie wurde ins Logbuch geklebt – der erste echte «Bug».": "In 1947, a real moth was found in a computer at Harvard University. It had caused an error. It was taped into the logbook – the first real “bug”.",
"1992 fielen 29 000 Plastik-Badetiere von einem Schiff in den Pazifik. Forscher verfolgten, wohin die Meeresströmungen sie trieben.": "In 1992, 29,000 plastic bath toys fell off a ship into the Pacific. Scientists tracked where the ocean currents carried them.",
"2 Kabelreste – für meine Stromleitung": "2 cable scraps – for my power line",
"20 Sekunden: Tipp auf die Risslinge (oder Taste 1 bis 9). Das Ei ist Piko, das bitte nicht hauen!": "20 seconds: tap the Cracklings (or keys 1 to 9). The egg is Piko – please don't bop it!",
"20 Wolkensprünge! Die Kapitänin zahlt dir 400 Taler Flugprämie.": "20 cloud jumps! The captain pays you a 400 Taler flight bonus.",
"25 Taler sprangen aus dem Stein!": "25 Taler jumped out of the stone!",
"3 Minuten lang doppelt so hoch springen.": "Jump twice as high for 3 minutes.",
