"Aale können über Land kriechen, wenn das Gras nass ist. So wechseln sie manchmal von einem Teich in den nächsten.": "Eels can crawl over land when the grass is wet. That way they sometimes move from one pond to the next.",
"Ab 1999 gab es den Euro nur als Buchgeld. Scheine und Münzen kamen erst am 1. Januar 2002.": "From 1999 the euro only existed as account money. Notes and coins only arrived on 1 January 2002.",
