"Ach, bevor ich es vergesse: Der Rat hat beschlossen, dir etwas zu schenken.": "Oh, before I forget: the council has decided to give you a present.",
"Ach, und in deiner Tasche liegt ein kleines Ei. Pass gut darauf auf.": "Oh, and there's a little egg in your bag. Take good care of it.",
