"Ah – du bist wach! Nicht erschrecken, du bist in meiner Praxis.": "Ah – you're awake! Don't be scared, you're in my clinic.",
"Ah, unser neuer Stern am Himmel!": "Ah, our new star in the sky!",
"Aha, ein Körpertausch! Such dir aus, wer du heute sein willst.": "Aha, a body swap! Choose who you want to be today.",
