"Art-déco-Innenstadt mit Wolkenkratzern, Taxis, Hafen und einem Jazz-Festival am Abend.": "Art deco city centre with skyscrapers, taxis, a harbour and a jazz festival in the evening.",
"Arthropleura war ein Tausendfüsser so lang wie ein Auto – das grösste Krabbeltier, das je an Land lebte. Er frass vermutlich Pflanzenreste im Wald.": "Arthropleura was a millipede as long as a car – the biggest creepy-crawly that ever lived on land. It probably ate plant remains in the forest.",
"As": "Ace",
"Aschefeld": "Ash field",
"Asseln sind Krebstiere, die an Land leben und totes Material zersetzen. Die USB-Assel frisst alte Kabel und rollt sich bei Gefahr zu einem ordentlichen Knäuel. Wer sie in einen Computer steckt, bekommt 5 Gigabyte Kompost-Fotos geschenkt.": "Woodlice are crustaceans that live on land and break down dead material. The USB woodlouse eats old cables and rolls up into a neat ball when in danger. Plug it into a computer and you get 5 gigabytes of compost photos as a gift.",
"Asseln sind keine Insekten, sondern Krebstiere – und atmen mit kiemenähnlichen Organen, weshalb sie Feuchtigkeit brauchen. Unter Steinen und Laub zersetzen sie tote Pflanzenteile. Sie sind die Müllabfuhr des Waldbodens, nur viel niedlicher.": "Woodlice aren't insects but crustaceans – and they breathe with gill-like organs, which is why they need moisture. Under stones and leaves they break down dead plant parts. They are the rubbish collectors of the forest floor, just much cuter.",
"Ast": "Branch",
"Atmet unter Wasser und riecht Erdbeben.": "Breathes under water and smells earthquakes.",
"Atrium-Mini-Brunnen": "Atrium mini fountain",
"Atrium-Platz": "Atrium Plaza",
"Atrium-Taube": "Atrium pigeon",
"Aua!": "Ouch!",
"Auch Landschnecken krochen über Baumrinde und blieben manchmal im Harz kleben.": "Land snails crawled over tree bark too and sometimes got stuck in the resin.",
"Auf CDs sind Daten als winzige Vertiefungen gespeichert, die ein Laser abtastet. Die Rillen brechen das Licht und machen daraus diesen Regenbogen-Schimmer – ganz ohne Farbe, wie beim Morphofalter. Leider bestehen CDs aus Polycarbonat und Alu und verrotten praktisch nie.": "On CDs, data is stored as tiny pits that a laser reads. The grooves bend the light and turn it into this rainbow shimmer – without any colour, like the morpho butterfly. Sadly CDs are made of polycarbonate and aluminium and practically never rot.",
"Auf Musikkassetten nahm man Lieblingslieder aus dem Radio auf und verschenkte sie als „Mixtape“ – eine Liebeserklärung in 60 Minuten. Wenn das Band verknotete, spulte man es mit einem Bleistift zurück. Magnetband speichert Daten übrigens bis heute: in riesigen Archiven.": "People recorded their favourite songs from the radio onto cassettes and gave them away as a “mixtape” – a declaration of love in 60 minutes. When the tape got tangled, you wound it back with a pencil. By the way, magnetic tape still stores data today: in huge archives.",
"Auf alten Karten füllten Zeichner unbekannte Gebiete mit Seeungeheuern und Fabelwesen. Die ersten genauen Weltkarten entstanden erst im 16. Jahrhundert.": "On old maps, artists filled unknown areas with sea monsters and mythical creatures. The first accurate world maps were only made in the 16th century.",
"Auf das Wolkenkissen springen": "Jump onto the cloud cushion",
"Auf deinen eigenen Planeten? Wie aufregend!": "To your own planet? How exciting!",
"Auf dem Kompost-Planeten. Ein freundliches Dörfchen, du wirst sehen.": "On the Compost planet. A friendly little village, you'll see.",
"Auf dem Magnetstreifen einer Karte sind Zahlen gespeichert, ähnlich wie auf einer Musikkassette.": "Numbers are stored on the magnetic strip of a card, much like on a music cassette.",
"Auf dem Planeten sind zwölf goldene Spielmarken versteckt. Jede bringt Tickets für die Spielhalle.": "Twelve golden tokens are hidden on the planet. Each one brings tickets for the arcade.",
"Auf dem grossen Bildschirm hüpft ein Logo. Wer es genau in eine Ecke lenkt, hat etwas geschafft, was fast niemand schafft.": "A logo bounces on the big screen. Whoever steers it exactly into a corner has done something almost nobody manages.",
"Auf der Sonnenseite doppelt so schnell.": "Twice as fast on the sunny side.",
"Auf diesem Planeten ist immer früher Abend. Lampions leuchten in den Bäumen, und auf dem Markt wird getauscht. Am Ende steigen Himmelslaternen auf.": "On this planet it is always early evening. Lanterns glow in the trees and people trade at the market. At the end, sky lanterns rise.",
"Auf eine Diskette passten 1,44 Megabyte – das ist weniger als ein einziges Handyfoto heute. Trotzdem lebt sie weiter: als „Speichern“-Knopf in fast jedem Programm. Das Museum lagert darauf seine Lieblingswitze. Alle drei.": "A floppy disk held 1.44 megabytes – less than a single phone photo today. Still, it lives on: as the “Save” button in almost every program. The museum keeps its favourite jokes on it. All three of them.",
"Auf jedem Planeten wohnen andere Tiere. Streicheln, füttern, Fangen spielen – und sie kommen mit dir mit!": "Different animals live on every planet. Pet them, feed them, play tag – and they come along with you!",
"Auf meinen Planeten einladen": "Invite to my planet",
"Auf unserem Planeten klingt alles. Wenn du still bist, hörst du die Harfenbäume im Wind.": "On our planet everything makes a sound. If you're quiet, you can hear the harp trees in the wind.",
"Auf vielen Stadtdächern stehen Bienenstöcke. Stadthonig ist oft besonders vielfältig, weil Städte viele verschiedene Pflanzen haben.": "There are beehives on many city roofs. City honey is often especially varied because cities have so many different plants.",
