"Axolotl können verlorene Beine – sogar Teile von Herz und Gehirn – einfach nachwachsen lassen.": "Axolotls can simply regrow lost legs – even parts of their heart and brain.",
"Axolotl sind Schwanzlurche, die ihr Leben lang wie Kaulquappen aussehen. Sie können Beine, Teile des Herzens und sogar des Gehirns nachwachsen lassen! In freier Wildbahn in Mexiko sind sie fast verschwunden – dieser hier hat sich eine Antenne gebastelt, um Verwandte zu finden.": "Axolotls are salamanders that look like tadpoles their whole life. They can regrow legs, parts of the heart and even of the brain! In the wild in Mexico they have almost disappeared – this one has built itself an antenna to find relatives.",
