"Barben tasten mit ihren Barteln am Grund nach Futter. Die Akku-Barbe speichert Sonnenwärme aus dem Kühlwasser in ihrem Bauch. Echte Akkus enthalten wertvolle Metalle wie Lithium und Kobalt – sie gehören nie in den Müll, sondern zum Recycling.": "Barbels feel for food on the bottom with their whiskers. The battery barbel stores sun warmth from the cooling water in its belly. Real batteries contain valuable metals like lithium and cobalt – they never belong in the bin, always in recycling.",
