"Bei Rentieren tragen auch die Weibchen ein Geweih. Es fällt jedes Jahr ab und wächst neu.": "In reindeer, the females have antlers too. They fall off every year and grow back.",
"Bei Rot bleiben alle in der Nähe stehen.": "At red, everyone nearby stops.",
"Bei Seepferdchen werden die Männchen schwanger: Sie tragen die Eier in einer Bauchtasche und bringen hunderte Babys zur Welt. Mit ihrem Greifschwanz halten sie sich an Seegras fest, damit die Strömung sie nicht wegträgt. Familie ist eben das, was man daraus macht.": "With seahorses, the males get pregnant: they carry the eggs in a belly pouch and give birth to hundreds of babies. With their gripping tail they hold on to seagrass so the current doesn't carry them away. Family is whatever you make of it.",
"Bei Wählscheiben-Telefonen drehte man für jede Ziffer eine Scheibe herum, und sie schnurrte zurück. Das Telefon hing an einer Kabelschnur – Laufen während des Telefonierens war nur im Radius von zwei Metern möglich. Diese Geräte hielten oft 40 Jahre. Heute schaffen Handys selten fünf.": "On rotary phones you turned a dial for every digit, and it whirred back. The phone hung on a cord – you could only walk around within two metres while talking. These phones often lasted 40 years. Today phones rarely make it to five.",
"Beilfisch": "Hatchetfish",
"Beilfische leuchten an der Unterseite genau so hell wie das Licht von oben. So sieht man ihren Schatten von unten nicht.": "Hatchetfish glow on their underside exactly as brightly as the light from above. That way you can't see their shadow from below.",
"Beim Angelspiel hat jeder Holzfisch ein Stück Metall oder einen Magneten. Die Angel hat auch einen Magneten – so «beissen» die Fische an.": "In the fishing game, every wooden fish has a piece of metal or a magnet. The rod has a magnet too – that's how the fish “bite”.",
"Beim Jazz-Festival mitspielen": "Play along at the jazz festival",
"Beim Morsealphabet besteht jeder Buchstabe aus kurzen und langen Signalen. «SOS» ist drei kurz, drei lang, drei kurz.": "In Morse code every letter is made of short and long signals. “SOS” is three short, three long, three short.",
"Beim Scharren wachsen Blumen.": "Flowers grow when it scratches the ground.",
"Beim grossen Rennen schliefen alle anderen ein, weil es so lange dauerte.": "In the big race everyone else fell asleep because it took so long.",
"Beim klassischen Origami wird nur ein einziges quadratisches Blatt verwendet – ohne Schere und ohne Kleber.": "In classic origami you only use one single square sheet – no scissors and no glue.",
