"Bernstein ist versteinertes Baumharz. Darin sind manchmal Insekten erhalten, die 100 Millionen Jahre alt sind. Eine Kassette ist allerdings neu.": "Amber is fossilised tree resin. Sometimes insects 100 million years old are preserved in it. A cassette, though, is new.",
"Bernstein ist versteinertes Baumharz. Das Harz floss über kleine Tiere und hielt sie für immer fest.": "Amber is fossilised tree resin. The resin flowed over small animals and held them forever.",
"Bernstein ist versteinertes Baumharz. Manchmal wurden darin Insekten, Pollen oder Federn eingeschlossen und bis heute perfekt erhalten. Dass man daraus Dinosaurier klonen kann, ist aber nur ein Film – die Erbinformation ist längst zerfallen.": "Amber is fossilised tree resin. Sometimes insects, pollen or feathers got trapped in it and are perfectly preserved to this day. That you could clone dinosaurs from it is only a film – the genetic information fell apart long ago.",
