"DANKE": "THANK YOU",
"Da bist du ja! Dr. Bolzen hat mir schon alles erzählt.": "There you are! Dr. Bolt has already told me everything.",
"Da fehlen dir noch ein paar Taler. Aufträge helfen!": "You're still a few Taler short. Jobs help!",
"Da ist etwas runtergefallen!": "Something fell down!",
"Da ist kein Platz.": "There's no room there.",
"Da sangen ihm die Sterne ein Schlaflied. Und seitdem schläft der Mond tagsüber – ganz dünn, fast unsichtbar.": "Then the stars sang him a lullaby. And ever since, the moon sleeps during the day – very thin, almost invisible.",
"Da wären wir! Danke, dass du mit Taxi-Toni gefahren bist.": "Here we are! Thanks for riding with Taxi Toni.",
"Da! Ein Regenbogen. Wo er den Boden berührt, soll ein Topf stehen …": "Look! A rainbow. Where it touches the ground, there's supposed to be a pot …",
"Dach ": "Roof ",
