"Einrad": "Unicycle",
"Einrichten": "Furnish",
"Einrichten: Möbel wählen, auf den Boden tippen. R dreht, Esc beendet.": "Furnishing: pick furniture, tap the floor. R rotates, Esc finishes.",
"Einrichtung": "Furnishings",
