"Einschluss ": "Inclusion ",
"Einsiedlerkrebs": "Hermit crab",
"Einsiedlerkrebse haben einen weichen Hinterleib und leihen sich leere Schneckenhäuser als Zuhause. Wird das Haus zu klein, stellen sie sich in einer Schlange an und tauschen der Grösse nach durch – eine Wohnungsbörse am Strand. Leider ziehen manche heute in Plastikmüll ein.": "Hermit crabs have a soft rear body and borrow empty snail shells as homes. When the house gets too small, they line up in a queue and swap by size – a housing exchange on the beach. Sadly some move into plastic rubbish today.",
"Einsiedlerkrebse ziehen immer wieder in grössere Schneckenhäuser um. Manchmal stehen sie Schlange und tauschen der Grösse nach.": "Hermit crabs keep moving into bigger snail shells. Sometimes they queue up and swap by size.",
"Einsiedlerkrebse ziehen in grössere Schneckenhäuser um – manchmal stellen sie sich dafür in einer Warteschlange nach Grösse auf!": "Hermit crabs move into bigger snail shells – sometimes they even line up in a queue by size for it!",
