"Ente": "Duck",
"Enten haben wasserdichte Federn: Sie fetten sie mit einem Öl aus einer Drüse am Schwanz ein.": "Ducks have waterproof feathers: they grease them with oil from a gland near their tail.",
"Entenfüsse": "Duck feet",
"Entfernen": "Remove",
"Entfernt Ölflecken und Schmutz.": "Removes oil stains and dirt.",
"Er beneidete die Sonne, die abends einfach unterging und träumte.": "He envied the sun, which simply set in the evening and dreamed.",
"Er fand eine Giesskanne und eine vertrocknete Blume.": "He found a watering can and a dried-up flower.",
"Er ist entkommen …": "It got away …",
"Er ist fertig! Der Riesen-Dino läuft zum ersten Mal seit 1999.": "It's finished! The giant dino is walking for the first time since 1999.",
"Er schliff zwei Tautropfen, bis sie ganz rund und glatt waren.": "He polished two dewdrops until they were perfectly round and smooth.",
"Er wurde abgeschafft": "It was abolished",
"Er wurde eingeführt, zuerst aber nur auf Konten": "It was introduced, but at first only in accounts",
