"Erdmännchen stellen Wachen auf: Eines passt auf und warnt die Gruppe mit verschiedenen Rufen für Adler oder Schlangen.": "Meerkats post guards: one keeps watch and warns the group with different calls for eagles or snakes.",
"Erfasst Cyborgs in der Nähe und markiert sie rot.": "Detects nearby cyborgs and marks them red.",
