"Erwischt! ": "Caught! ",
"Erwischt! Deine Tasche ist voll, darum gibt es 10 Tickets.": "Caught! Your bag is full, so you get 10 tickets.",
"Erzähl mir vom Planeten": "Tell me about the planet",
"Es": "It",
"Es fehlen: ": "Missing: ",
"Es gab ihn sofort als Münzen im Portemonnaie": "It was immediately available as coins in your wallet",
"Es ist noch hell draussen – Nickerchen statt Nachtruhe.": "It's still light outside – a nap instead of a night's sleep.",
"Es war einmal ein Mond, der jede Nacht wach bleiben musste.": "Once upon a time there was a moon that had to stay awake every night.",
