"Etwas Neues anziehen?": "Put on something new?",
"Etwas spenden": "Donate something",
"Etwas verkaufen": "Sell something",
"Euer Cyborg wohnt ab jetzt auf dem Kompost-Planeten. Damit er in die gemeinsame Welt am Beamer kommt, kopiert den Code und schickt ihn an den Beamer-Laptop (Miro-Board oder Klassenchat).": "From now on your cyborg lives on the Compost Planet. To bring it into the shared world on the projector, copy the code and send it to the projector laptop (Miro board or class chat).",
"Eulen fliegen fast lautlos: Die Kanten ihrer Federn sind gezackt wie ein Kamm und brechen die Luftwirbel.": "Owls fly almost silently: the edges of their feathers are jagged like a comb and break up the air swirls.",
"Eulen können ihren Kopf um 270 Grad drehen. Ihre Augen sind so gross, dass sie sich in den Augenhöhlen nicht bewegen lassen.": "Owls can turn their heads 270 degrees. Their eyes are so big they can't move in their sockets.",
"Eulenaugen": "Owl eyes",
"Eulenfalter sind nachtaktive Motten mit dichtem Haarkleid, das sie in kalten Nächten warm hält.": "Owlet moths are night-active moths with a thick coat of hair that keeps them warm on cold nights.",
"Eulenkopf": "Owl head",
"Europäische Aale schwimmen tausende Kilometer bis in die Sargassosee zum Laichen. Wie sie den Weg finden, ist bis heute nicht ganz geklärt.": "European eels swim thousands of kilometres to the Sargasso Sea to spawn. How they find the way is still not fully understood.",
"Europäische Aale schwimmen zum Laichen tausende Kilometer bis in die Sargassosee. Ihre Larven treiben dann jahrelang zurück nach Europa.": "European eels swim thousands of kilometres to the Sargasso Sea to spawn. Their larvae then drift back to Europe for years.",
"Eurypteriden, die Seeskorpione, lebten vor über 400 Millionen Jahren im Wasser. Manche waren über zwei Meter lang – die grössten Gliederfüsser aller Zeiten.": "Eurypterids, the sea scorpions, lived in the water over 400 million years ago. Some were over two metres long – the biggest arthropods of all time.",
