"Farne gab es schon vor über 350 Millionen Jahren. Aus riesigen Farn- und Schachtelhalm-Wäldern entstand später Steinkohle. Wer Kohle verbrennt, verbrennt also uralte Wälder – und deren gespeichertes CO₂ landet wieder in der Luft.": "Ferns existed over 350 million years ago. Huge forests of ferns and horsetails later turned into coal. So whoever burns coal burns ancient forests – and their stored CO₂ ends up back in the air.",
"Farne gibt es seit über 350 Millionen Jahren – lange vor den Dinosauriern. Sie vermehren sich mit Sporen statt mit Samen.": "Ferns have existed for over 350 million years – long before the dinosaurs. They reproduce with spores instead of seeds.",
