"Fische filtern mit ihren Kiemen Sauerstoff aus dem Wasser – ein Router filtert Datenpakete aus dem Rauschen. Der Kiemen-Router macht beides und blinkt dabei zufrieden. Wenn nachts alle Lichter grün sind, ist das Kühlwasser sauber.": "Fish filter oxygen from the water with their gills – a router filters data packets from the noise. The gill router does both and blinks contentedly while doing it. When all the lights are green at night, the cooling water is clean.",
