"Fledermäuse rufen beim Fliegen ganz hohe Töne und hören das Echo. So «sehen» sie im Dunkeln mit den Ohren.": "Bats call out very high sounds when flying and listen to the echo. That's how they “see” in the dark with their ears.",
"Fleischfressende Dinosaurier verloren ständig Zähne und bekamen einfach neue – ein Leben lang. Die kleinen Sägezähne an der Kante funktionierten wie ein Steakmesser. Heute leben die Nachfahren der Dinosaurier noch unter uns: die Vögel.": "Meat-eating dinosaurs constantly lost teeth and simply grew new ones – their whole life long. The little saw teeth along the edge worked like a steak knife. Today the dinosaurs' descendants still live among us: the birds.",
