"Flugsaurier waren keine Dinosaurier, sondern ihre Cousins. Ihre Flügel waren Hautsegel, die an einem extrem langen vierten Finger hingen.": "Pterosaurs weren't dinosaurs but their cousins. Their wings were skin sails hanging from an extremely long fourth finger.",
"Flugsaurier-Schädel": "Pterosaur skull",
"Flussbarsch": "Perch",
"Flussbarsche jagen oft im Team und treiben kleine Fische in die Enge. Ihre Rückenflosse ist stachelig – vorsichtig anfassen!": "Perch often hunt as a team and drive small fish into a corner. Their back fin is spiny – handle with care!",
"Flussbarsche tragen dunkle Querstreifen und leuchtend rote Bauchflossen. Ihre stachelige Rückenflosse stellen sie auf, wenn ihnen jemand zu nahe kommt. Auf dem Kompost-Planeten stehen sie am liebsten dort, wo Weidenwurzeln ins Wasser hängen.": "Perch have dark stripes and bright red belly fins. They raise their spiny back fin when someone gets too close. On the Compost Planet they like to stand where willow roots hang into the water.",
"Flöckchen": "Little flake",
