"Folge dem Weg vom Dorfplatz zum Laden. Dort kannst du alles verkaufen, was du findest, und Möbel kaufen.": "Follow the path from the village square to the shop. There you can sell everything you find and buy furniture.",
"Folge den leuchtenden Säulen. Erst wenn alles repariert ist, kannst du wieder starten.": "Follow the glowing pillars. You can only take off again once everything is repaired.",
"Form": "Shape",
"Forschende finden ganze Nester versteinerter Dino-Eier. Manche Dinos bebrüteten ihre Eier wie Vögel – ein Hinweis, dass Vögel wirklich ihre Nachfahren sind.": "Researchers find whole nests of fossilised dino eggs. Some dinos brooded their eggs like birds – a sign that birds really are their descendants.",
