"Frösche": "Frogs",
"Frösche haben Schallblasen, die wie Lautsprecher wirken. Manche Froscharten sind so laut, dass man sie kilometerweit hört.": "Frogs have vocal sacs that work like loudspeakers. Some frog species are so loud you can hear them kilometres away.",
"Frösche trinken nicht mit dem Maul – sie nehmen Wasser über die Haut auf.": "Frogs don't drink with their mouth – they take in water through their skin.",
"Frühe tragbare Konsolen liefen mit AA-Batterien stundenlang. Heute landen jedes Jahr Millionen Geräte im Elektroschrott – Reparieren lohnt sich!": "Early handheld consoles ran for hours on AA batteries. Today millions of devices end up as electronic scrap every year – repairing is worth it!",
"Früher bekamen Computer ihre Programme auf Lochkarten. Ein Loch hiess 1, kein Loch hiess 0. Für ein Programm brauchte man oft hunderte Karten.": "Computers used to get their programs on punched cards. A hole meant 1, no hole meant 0. One program often needed hundreds of cards.",
"Früher druckten manche Spielautomaten die besten Punktzahlen aus oder speicherten nur drei Buchstaben pro Name.": "Some arcade machines used to print out the best scores or saved only three letters per name.",
"Früher hielt man Laubfrösche im Glas mit einer kleinen Leiter. Kletterte der Frosch hoch, sollte gutes Wetter kommen. Er wollte aber nur Fliegen fangen.": "People used to keep tree frogs in a jar with a little ladder. If the frog climbed up, good weather was supposed to come. But it just wanted to catch flies.",
"Früher lief auf unserem Mond alles im gleichen Takt. Dann sind die sechs Aufzieh-Wächter stehen geblieben.": "Everything on our moon used to run in the same rhythm. Then the six wind-up guardians stopped.",
"Früher verschloss man Briefe mit Wachssiegeln. War das Siegel kaputt, wusste man: Jemand hat den Brief schon geöffnet.": "Letters used to be closed with wax seals. If the seal was broken, you knew someone had already opened the letter.",
"Früher war das hier eine Müllhalde. Heute bauen wir aus allem etwas Neues.": "This used to be a rubbish dump. Today we build something new out of everything.",
"Früher waren wir normal gross. Dann hat jemand am Schrumpfhebel gespielt. Aber ehrlich: So ist es viel gemütlicher.": "We used to be normal size. Then someone played with the shrinking lever. But honestly: it's much cosier like this.",
