"Fährt Treppen hoch und macht Rampen überflüssig.": "Climbs stairs and makes ramps unnecessary.",
"Fährten zeigen, wie Dinos liefen: wie schnell, ob allein oder in Herden. Manche Spuren wurden in Schlamm gedrückt, der dann austrocknete und versteinerte.": "Tracks show how dinos walked: how fast, alone or in herds. Some tracks were pressed into mud that then dried and turned to stone.",
"Fässer": "Barrels",
"Föhn": "Warm wind",
"Füchse hören so gut, dass sie eine Maus unter dem Schnee quieken hören. Dann springen sie hoch und landen genau darauf.": "Foxes hear so well that they can hear a mouse squeak under the snow. Then they jump up and land right on it.",
"Füge zuerst jemanden als Freund:in hinzu.": "Add someone as a friend first.",
"Fügt Kunstcodes ein (beginnen mit ART1.). Mehrere dürfen untereinander stehen.": "Paste art codes (they start with ART1.). Several may go one below the other.",
"Fügt hier alle Codes ein, die ihr bekommen habt. Mehrere Codes dürfen einfach untereinander stehen.": "Paste all the codes you received here. Several codes can simply go one below the other.",
