"Fünf Funkbaken senden irgendwo da draussen. Sieh auf deinen Peilempfänger: Je mehr Balken, desto näher bist du.": "Five radio beacons are transmitting somewhere out there. Look at your direction finder: the more bars, the closer you are.",
"Fünf Händlerinnen tauschen gern. Fang beim Teestand an, dann führt eins zum anderen.": "Five traders like to swap. Start at the tea stall, then one thing leads to another.",
"Fünf Messstationen zeigen, wie man Wetter misst. Wer alle kennt, darf sogar Polarlicht machen.": "Five measuring stations show how weather is measured. Whoever knows them all may even make northern lights.",
"Fünf Pusteblumen-Flüge! Der Wind schenkt dir 300 Taler.": "Five dandelion flights! The wind gives you 300 Taler.",
"Fünf Sterne! Wir sind das schönste Dorf im ganzen Sonnensystem!": "Five stars! We are the most beautiful village in the whole solar system!",
"Fünf grosse Server-Schränke sind ganz zugewuchert. Wenn du die Ranken abschneidest, starten sie wieder.": "Five big server racks are completely overgrown. If you cut the vines, they start up again.",
"Für Schüler:innen": "For students",
"Für den Fall, dass der Lift wieder kaputt ist.": "In case the lift is broken again.",
"Für dich: ein Weltempfänger. Mit ihm hörst du jeden Sender im Sonnensystem.": "For you: a world receiver. With it you can hear every station in the solar system.",
"Für die Lehrperson": "For the teacher",
"Für die Lehrperson am Beamer: Codes der Gruppen einschleusen, damit alle Cyborgs auf einem Planeten wohnen. Die Welt wird in diesem Browser gespeichert.": "For the teacher at the projector: smuggle in the groups' codes so all cyborgs live on one planet. The world is saved in this browser.",
"Für die Lehrperson: Codes der Gruppen einschleusen oder die Welt sichern.": "For the teacher: smuggle in the groups' codes or back up the world.",
"Für ein Glas Honig fliegen Bienen zusammen eine Strecke, die mehrmals um die ganze Erde reicht.": "For one jar of honey, bees together fly a distance that goes around the whole Earth several times.",
"Für einen Kranich brauchst du ein Buntpapier. Es liegt überall auf den Wiesen herum.": "For a crane you need a sheet of coloured paper. They lie all over the meadows.",
