"Glühwürmchen erzeugen kaltes Licht fast ohne Wärmeverlust. Jede Art blinkt in ihrem eigenen Morsecode.": "Fireflies make cold light with almost no heat loss. Every species blinks in its own Morse code.",
"Glühwürmchen sind eigentlich Käfer, die mit einer chemischen Reaktion kaltes Licht erzeugen – fast ohne Wärmeverlust. Männchen und Weibchen blinken sich Morse-artige Liebesbotschaften zu. Lichtverschmutzung durch Strassenlampen macht es ihnen schwer, sich zu finden.": "Fireflies are actually beetles that make cold light with a chemical reaction – almost without losing heat. Males and females blink Morse-like love messages to each other. Light pollution from street lamps makes it hard for them to find each other.",
"Glühwürmchen sind eigentlich Käfer. Ihr Licht ist «kalt»: Fast die ganze Energie wird zu Licht und kaum etwas zu Wärme.": "Fireflies are actually beetles. Their light is “cold”: almost all the energy becomes light and hardly any becomes heat.",
