"Goldfische stammen von chinesischen Karauschen ab und wurden vor über 1000 Jahren gezüchtet. Das Gerücht vom 3-Sekunden-Gedächtnis stimmt nicht: Sie merken sich Dinge monatelang. Bitte nie in Teiche aussetzen – dort verdrängen sie heimische Arten.": "Goldfish descend from Chinese crucian carp and were bred over 1000 years ago. The rumour of a 3-second memory isn't true: they remember things for months. Please never release them into ponds – there they push out native species.",
"Goldfischglas": "Goldfish bowl",
