"Gottesanbeterin-Klingen": "Mantis blades",
"Gottesanbeterinnen können ihren Kopf fast rundherum drehen und sehen sogar dreidimensional. Mit ihren Fangarmen schnappen sie in Sekundenbruchteilen zu. Viele Arten tarnen sich perfekt als Blüte oder Blatt – Blumen mit Hunger, sozusagen.": "Praying mantises can turn their head almost all the way round and even see in three dimensions. They snap with their catching arms in a fraction of a second. Many species camouflage themselves perfectly as a flower or leaf – flowers with an appetite, so to speak.",
"Graben": "Ditch",
