"Grillen hören mit Ohren an den Vorderbeinen. Am Tempo ihres Zirpens kann man sogar ungefähr die Temperatur ablesen.": "Crickets hear with ears on their front legs. From the speed of their chirping you can even roughly read the temperature.",
"Grillen zirpen schneller, wenn es warm ist. Zählt man die Zirper in 14 Sekunden und addiert 40, bekommt man ungefähr die Temperatur in Fahrenheit.": "Crickets chirp faster when it's warm. Count the chirps in 14 seconds and add 40, and you get roughly the temperature in Fahrenheit.",
"Grillen zirpen schneller, wenn es wärmer ist. Aus der Zahl der Zirper pro Minute kann man ungefähr die Temperatur ablesen.": "Crickets chirp faster when it's warmer. From the number of chirps per minute you can roughly read the temperature.",
"Grillen zirpen, indem sie einen Flügel mit einer Schrillleiste über eine Kante am anderen Flügel reiben.": "Crickets chirp by rubbing a wing with a file-like ridge over an edge on the other wing.",
"Grillen zirpen, indem sie ihre Flügel aneinander reiben. Je wärmer es ist, desto schneller zirpen sie.": "Crickets chirp by rubbing their wings together. The warmer it is, the faster they chirp.",
"Grillen-Männchen zirpen, um Weibchen anzulocken. Jede Grillenart hat ihr eigenes Lied, an dem sie sich erkennen.": "Male crickets chirp to attract females. Every cricket species has its own song by which they recognise each other.",
"Grillzange": "Grill tongs",
"Grimasse": "Grimace",
