"Grundeln haben am Bauch eine Saugscheibe. Damit halten sie sich an Steinen fest, auch wenn das Wasser stark strömt.": "Gobies have a suction disc on their belly. They use it to hold on to stones even in strong currents.",
"Grundeln leben am Boden und können manchmal sogar kurze Strecken über Land hüpfen. Sie haben grosse Augen oben am Kopf.": "Gobies live on the bottom and can sometimes even hop short distances over land. They have big eyes on top of their head.",
"Gräbt eine Senke, die sich mit Wasser füllt.": "Digs a hollow that fills with water.",
"Grüne Berge, Flusstäler, Mangroven und drei überwucherte Tempel. Hier schwingt man an Lianen.": "Green mountains, river valleys, mangroves and three overgrown temples. Here you swing on vines.",
"Grüne Socke": "Green sock",
