"Guppy-Männchen sind bunt, um Weibchen zu beeindrucken – aber auffällige Farben locken auch Räuber an. Ein ständiger Balanceakt.": "Male guppies are colourful to impress females – but bright colours also attract predators. A constant balancing act.",
"Guppys gehören zu den buntesten Aquarienfischen der Welt, jedes Männchen ist ein bisschen anders gemustert. Der Pixel-Guppy lebt im Kühlwasser alter Bildschirme und hat sich deren Auflösung angewöhnt. Wenn man ganz nah rangeht, sieht man die Kästchen.": "Guppies are among the most colourful aquarium fish in the world; every male is patterned a little differently. The pixel guppy lives in the cooling water of old screens and has picked up their resolution. If you get really close, you can see the squares.",
"Guppys legen keine Eier. Die Jungen kommen lebend und schwimmend zur Welt.": "Guppies don't lay eggs. The young are born alive and swimming.",
