"Hagelkörner wachsen in Gewitterwolken: Aufwinde tragen sie immer wieder nach oben, und jedes Mal friert eine neue Eisschicht an.": "Hailstones grow in thunderclouds: updrafts carry them up again and again, and each time a new layer of ice freezes on.",
"Haie gibt es seit über 400 Millionen Jahren – sie sind älter als die ersten Bäume! Riffhaie halten als Spitzenräuber das ganze Korallenriff im Gleichgewicht. Menschen sind für Haie viel gefährlicher als umgekehrt: Jedes Jahr werden Millionen gefangen.": "Sharks have existed for over 400 million years – they are older than the first trees! As top predators, reef sharks keep the whole coral reef in balance. Humans are far more dangerous to sharks than the other way round: millions are caught every year.",
