"Hasen können ihre langen Ohren einzeln drehen und so Geräusche aus allen Richtungen hören, ohne den Kopf zu bewegen.": "Hares can turn their long ears separately and so hear sounds from all directions without moving their head.",
"Hasen können über 70 km/h schnell laufen und Haken schlagen. Anders als Kaninchen kommen ihre Jungen mit Fell und offenen Augen zur Welt.": "Hares can run over 70 km/h and zigzag. Unlike rabbits, their young are born with fur and open eyes.",
"Hasen und Kaninchen fressen einen Teil ihres Kots ein zweites Mal. So holen sie wichtige Vitamine aus der Pflanzennahrung heraus.": "Hares and rabbits eat part of their droppings a second time. That way they get important vitamins out of their plant food.",
"Hasenbabys kommen mit Fell und offenen Augen zur Welt. Kaninchenbabys dagegen sind anfangs nackt und blind.": "Baby hares are born with fur and open eyes. Baby rabbits, on the other hand, are naked and blind at first.",
"Hast du Snacks?": "Do you have snacks?",
"Hast du das auch gesehen? Alles war plötzlich grau … und es roch nach Frühstück.": "Did you see that too? Everything was suddenly grey … and it smelled of breakfast.",
"Hast du einen Wunsch?": "Do you have a wish?",
"Hast du gehört? Die Bürgermeisterin hat denselben Witz zweimal erzählt. Wort für Wort.": "Did you hear? The mayor told the same joke twice. Word for word.",
"Hast du schon den Kiosk besucht? Da gibt es neue Möbel.": "Have you visited the kiosk yet? There's new furniture.",
