"Hecht": "Pike",
"Hechte lauern bewegungslos im Schilf und schiessen blitzschnell los. Sie sind wichtig für ein gesundes Gewässer, weil sie kranke Fische fressen.": "Pike lurk motionless in the reeds and shoot off in a flash. They are important for healthy waters because they eat sick fish.",
"Hechte lauern regungslos im Schilf und schnellen dann blitzartig vor. Ihr Maul ist voller nach hinten gebogener Zähne.": "Pike lurk motionless in the reeds and then dart forward like lightning. Their mouth is full of backward-curved teeth.",
"Hechte lauern regungslos zwischen Wasserpflanzen und schiessen dann blitzschnell hervor. Ihr Maul erinnert an einen Entenschnabel. Sie halten Fischbestände gesund, weil sie vor allem kranke und schwache Tiere erwischen.": "Pike lurk motionless between water plants and then shoot out in a flash. Their mouth looks like a duck's bill. They keep fish populations healthy because they mostly catch sick and weak animals.",
