"Heringe leben in riesigen Schwärmen und verständigen sich angeblich mit Luftbläschen, die sie aus dem Darm entlassen. Ja, wirklich.": "Herring live in huge shoals and are said to communicate with air bubbles they let out of their gut. Yes, really.",
"Heringe leben in riesigen Schwärmen. Nachts verständigen sie sich mit leisen Blubbergeräuschen aus Luftbläschen.": "Herring live in huge shoals. At night they communicate with quiet burbling sounds made of air bubbles.",
