"Heuschrecken und Grillen „geigen“: Sie streichen eine Reihe winziger Zähnchen am Bein über eine Kante am Flügel – wie ein Bogen über Saiten.": "Grasshoppers and crickets “fiddle”: they stroke a row of tiny teeth on their leg over an edge on their wing – like a bow over strings.",
"Heuschrecken zirpen, indem sie ihre Hinterbeine an den Flügeln reiben – wie ein Bogen auf einer Geige.": "Grasshoppers chirp by rubbing their hind legs against their wings – like a bow on a violin.",
"Heuschrecken zirpen, indem sie ihre Hinterbeine an den Flügeln reiben – wie ein Geigenbogen. Sie hören mit Ohren an den Beinen! Mit ihren kräftigen Sprungbeinen springen sie das Zwanzigfache ihrer Körperlänge weit.": "Grasshoppers chirp by rubbing their hind legs against their wings – like a violin bow. They hear with ears on their legs! With their strong jumping legs they leap twenty times their body length.",
"Heute Abend geben wir ein Konzert – für dich!": "Tonight we're giving a concert – for you!",
"Heute Nacht hast du schon ein Sternbild entdeckt. Morgen Nacht wartet das nächste.": "You've already discovered a constellation tonight. The next one awaits tomorrow night.",
"Heute ist ein Glitzertag!": "Today is a glitter day!",
"Heute ist er der Gärtner des schönsten Parks im ganzen System. Niemand sagt mehr etwas.": "Today he is the gardener of the most beautiful park in the whole system. Nobody says anything any more.",
"Heute ist perfektes Angelwetter!": "Today is perfect fishing weather!",
"Heute noch ": "Left today: ",
"Heute waren es schon 4 Millimeter.": "Today it was already 4 millimetres.",
"Heute? Also…": "Today? Well…",
"Hey du, stylisch wie immer!": "Hey you, stylish as always!",
"Hey! Das fand ich jetzt nicht witzig.": "Hey! I didn't think that was funny.",
"Hey! Kurz Liegestütze?": "Hey! Quick push-ups?",
"Hey! Pass gut auf dich auf, ja?": "Hey! Take good care of yourself, okay?",
"Hier beisst heute nichts.": "Nothing's biting here today.",
"Hier bleiben": "Stay here",
"Hier einpflanzen": "Plant here",
"Hier fehlen noch ": "Still missing here: ",
"Hier gibt es Mode für jeden Körper – und die neueste Kollektion von ": "Here there's fashion for every body – and the latest collection from ",
"Hier gibt es nichts zu glätten.": "There's nothing to smooth here.",
"Hier gibt es zu wenige Häuser.": "There are too few houses here.",
"Hier im Pavillon wohnen alle Fische und Insekten, die du gefangen hast.": "All the fish and insects you've caught live here in the pavilion.",
"Hier ist die Bernstein-Lampe. Und zur Erinnerung ein kleines Stück Urzeit-Spielzeug.": "Here is the amber lamp. And as a keepsake, a little piece of prehistoric toy.",
"Hier ist die Goldene Kundenkarte. Und ein Mini-Brunnen für dein Zimmer, ganz ohne Kassenbon.": "Here is the Golden Customer Card. And a mini fountain for your room, no receipt needed.",
"Hier ist ein Bauplatz (": "Here is a building site (",
"Hier ist ein Mini-Bildschirm mit Sternen-Schoner für dein Zimmer. Und der erste Bildschirmschoner überhaupt.": "Here is a mini screen with a star screensaver for your room. And the very first screensaver ever.",
"Hier ist ein Mondkuchen für dich. Und jetzt: Schau nach oben!": "Here is a mooncake for you. And now: look up!",
"Hier ist ein silbernes Glöckchen. Der Mondkuchen-Bäcker wartet schon auf ein Signal.": "Here is a little silver bell. The mooncake baker is already waiting for a signal.",
"Hier ist eine Kugelbahn für dein Zimmer. Und der allererste Bauklotz für das Museum.": "Here is a marble run for your room. And the very first building block for the museum.",
"Hier ist es kalt, aber die Herzen sind warm.": "It's cold here, but the hearts are warm.",
"Hier ist ja niemand, über den man reden könnte!": "There's nobody here to talk about!",
"Hier ist kein guter Platz zum Pflanzen.": "This isn't a good place for planting.",
"Hier kaufen und verkaufen. Neu heute: gut und klein.": "Buy and sell here. New today: good and small.",
"Hier leben viele Cyborgs – und alle haben ihren eigenen Tag.": "Lots of cyborgs live here – and each of them has their own day.",
"Hier liegen noch zwei Eier. Eins hast du heute schon mitgenommen – die anderen brauchen ihre Eltern.": "Two more eggs lie here. You've already taken one today – the others need their parents.",
"Hier muss niemand etwas kaufen. Viele kommen nur wegen der Springbrunnen und der Palmen.": "Nobody has to buy anything here. Lots of people only come for the fountains and the palms.",
"Hier sind 1000 Taler als Startgeld.": "Here are 1000 Taler as starting money.",
"Hier werden seit 1999 Plastik-Dinos gegossen. Spritzguss-Bäume, Schraubenpalmen und Granulat-Dünen. Bau den Riesen-Dino zusammen.": "Plastic dinos have been moulded here since 1999. Injection-moulded trees, screw palms and granule dunes. Put the giant dino together.",
"Hier wird das Wetter gemacht. An der Wettermaschine bestimmst du selbst, ob es regnet, schneit oder einen Regenbogen gibt.": "This is where the weather is made. At the weather machine you decide yourself whether it rains, snows or there's a rainbow.",
"Hier wird nichts weggeworfen, nur umgebaut.": "Nothing gets thrown away here, only rebuilt.",
"Hier, ": "Here, ",
"Hier, als Dankeschön: ": "Here, as a thank-you: ",
"Hier, ein Magnetbahn-Modell. Der kleine Zug fährt ganz von allein im Kreis.": "Here, a maglev model. The little train goes round in a circle all by itself.",
"Hier, ein eigener Kapselautomat für dein Zimmer. Und dein Name steht jetzt ganz oben auf der Highscore-Tafel.": "Here, your own capsule machine for your room. And your name is now right at the top of the high-score board.",
"Hier, nimm das als Dankeschön!": "Here, take this as a thank-you!",
