"Illustrations-Atelier": "Illustration studio",
"Im Baum hängen schon ": "Already hanging in the tree: ",
"Im Bernstein findet man oft winzige Mücken. Das Harz hat sie vor Millionen Jahren eingeschlossen und bis heute erhalten.": "Tiny mosquitoes are often found in amber. The resin trapped them millions of years ago and preserved them until today.",
"Im Fell von Faultieren wachsen winzige Algen. Darum sieht ihr Fell oft grünlich aus – eine perfekte Tarnung im Baum.": "Tiny algae grow in sloths' fur. That's why their fur often looks greenish – perfect camouflage in a tree.",
"Im Haus aufstellen": "Place in the house",
"Im Höcker speichert das Kamel Fett, nicht Wasser. Trinken kann es aber über 100 Liter auf einmal.": "A camel stores fat in its hump, not water. But it can drink over 100 litres at once.",
"Im Museum ausstellen": "Display in the museum",
"Im Rennraum": "In the race room",
"Im grossen Bienenstock tanzt eine Biene. Ihr Tanz zeigt dir den Weg zu einer versteckten Blütenwiese.": "A bee is dancing in the big beehive. Its dance shows you the way to a hidden flower meadow.",
"Imker-Hut": "Beekeeper hat",
"Imker-Mode": "Beekeeper fashion",
"Imki": "Beeky",
"In Australien wandern Bogong-Falter jedes Jahr über 1000 Kilometer in dieselben Berghöhlen. Sie spüren dabei das Magnetfeld der Erde.": "In Australia, bogong moths migrate over 1000 kilometres to the same mountain caves every year. They sense the Earth's magnetic field along the way.",
"In Bernstein aus Myanmar fand man Federn von kleinen Dinosauriern. Viele Dinos hatten also Federn.": "Feathers of small dinosaurs were found in amber from Myanmar. So many dinos had feathers.",
"In Bernstein, also versteinertem Baumharz, sind Insekten oft Millionen Jahre perfekt erhalten. Dinosaurier-DNA kann man daraus aber leider nicht holen – die zerfällt viel schneller.": "In amber, fossilised tree resin, insects are often perfectly preserved for millions of years. Sadly you can't get dinosaur DNA out of it – it breaks down much faster.",
"In Japan hängt man zum Kindertag Koi-Fahnen auf, die Koinobori. Der Koi steht für Kraft, weil er gegen den Strom schwimmt.": "In Japan people hang up koi flags, the koinobori, on Children's Day. The koi stands for strength because it swims against the current.",
"In Japan sagt man: Wer tausend Papierkraniche faltet, dem wird ein Wunsch erfüllt. Kraniche gelten dort als Glücksbringer.": "In Japan they say: whoever folds a thousand paper cranes gets a wish granted. Cranes are considered lucky there.",
"In Spieldosen zupft eine Walze mit kleinen Stiften an einem Stahlkamm. Jeder Zahn des Kamms ist genau auf einen Ton gestimmt.": "In music boxes a cylinder with little pins plucks a steel comb. Every tooth of the comb is tuned to exactly one note.",
"In Stadtbrunnen landen jährlich viele Münzen. Manche Städte spenden das Geld – ein Goldfisch darin hat also einen sehr gemeinnützigen Arbeitsplatz.": "Lots of coins land in city fountains every year. Some cities donate the money – so a goldfish in there has a very charitable job.",
"In Wüsten wie der Gobi wurden ganze Nester versteinerter Dino-Eier gefunden. Manche Dinos brüteten ihre Eier aus wie Vögel.": "Whole nests of fossilised dino eggs were found in deserts like the Gobi. Some dinos hatched their eggs like birds.",
"In Wüstenoasen leben oft Fische, die seit Jahrtausenden isoliert sind. Manche Arten gibt es nur in einer einzigen Quelle auf der ganzen Welt.": "Desert oases are often home to fish that have been isolated for thousands of years. Some species exist in only a single spring in the whole world.",
"In acht grossen Bernsteinblöcken stecken Schätze aus der Urzeit. Nimm die Lupe und schau genau hin.": "Treasures from prehistoric times are hidden in eight big amber blocks. Take the magnifying glass and look closely.",
"In alten Videospielen konnten sich Figuren oft nur in vier Richtungen bewegen: hoch, runter, links und rechts.": "In old video games, characters could often only move in four directions: up, down, left and right.",
"In deine Designs übernommen": "Added to your designs",
"In den 90ern fütterten Kinder auf der ganzen Welt pixelige Haustiere in Ei-förmigen Geräten – und waren traurig, wenn sie „starben“. Ein frühes Beispiel dafür, wie wir mit Maschinen Beziehungen eingehen. Donna Haraway würde sagen: Auch das ist eine Art Verwandtschaft.": "In the 90s, children all over the world fed pixelated pets in egg-shaped devices – and were sad when they “died”. An early example of how we form relationships with machines. Donna Haraway would say: that is a kind of kinship too.",
"In den Regenbogentopf greifen": "Reach into the rainbow pot",
"In den Spiegel schauen": "Look in the mirror",
"In den Spiegel schauen (Labor)": "Look in the mirror (lab)",
"In den drei Tempeln liegen alte Schiebe-Rätsel. Wer sie löst, findet die Schatzkammer.": "Old sliding puzzles lie in the three temples. Whoever solves them finds the treasure chamber.",
"In der Mega-Spielhalle gewinnt nicht das Glück, sondern die Übung.": "In the mega arcade it's practice that wins, not luck.",
"In der Tiefsee locken Anglerfische ihre Beute mit einer Leuchtangel, in der Bakterien Licht machen. Die winzigen Männchen verschmelzen mit dem Weibchen und werden ein Teil von ihr – Symbiose, wie sie im Buche steht. Der Glasfaser-Angler leuchtet mit echtem Datenlicht.": "In the deep sea, anglerfish lure their prey with a glowing rod in which bacteria make light. The tiny males fuse with the female and become part of her – symbiosis by the book. The fibre-optic angler glows with real data light.",
"In der Welt: ": "In the world: ",
"In der Wüste ist Wasser das Wertvollste.": "In the desert, water is the most precious thing.",
"In jeder Waschmaschine verschwinden angeblich Socken. In Wahrheit rutschen sie meist zwischen Trommel und Dichtung oder bleiben im Ärmel eines Pullovers hängen.": "Socks supposedly disappear in every washing machine. In truth they mostly slip between the drum and the seal or get stuck in a jumper sleeve.",
"In vielen Ländern erzählt man, man sehe auf dem Vollmond einen Hasen. Die dunklen Flecken sind in Wahrheit alte Lava-Ebenen.": "In many countries people say you can see a hare on the full moon. The dark spots are actually old lava plains.",
"In vielen alten Bibliotheken lebten Katzen, damit Mäuse die Bücher nicht anknabberten. Manche wurden richtig berühmt und hatten eigene Bibliotheksausweise.": "Cats lived in many old libraries so that mice wouldn't nibble the books. Some became really famous and had their own library cards.",
