"Jade war in vielen alten Kulturen Mittelamerikas wertvoller als Gold. Man verband den grünen Stein mit Wasser, Pflanzen und Leben.": "In many ancient cultures of Central America, jade was more valuable than gold. The green stone was linked with water, plants and life.",
"Jade-Frosch": "Jade frog",
"Jaguar-Casino": "Jaguar casino",
"Jaguare schwimmen gern und jagen sogar im Wasser. Ihr Name kommt vermutlich von einem Wort für „der mit einem Sprung tötet\".": "Jaguars like to swim and even hunt in the water. Their name probably comes from a word for “the one who kills with a single leap”.",
