"Je schneller es sich dreht, desto stärker weht der Wind.": "The faster it turns, the stronger the wind blows.",
"Je tiefer man taucht, desto stärker drückt das Wasser. In 10 Metern Tiefe ist der Druck schon doppelt so hoch wie an der Oberfläche.": "The deeper you dive, the harder the water presses. At 10 metres deep the pressure is already twice as high as at the surface.",
"Jede Nacht ein neues Sternbild entdecken.": "Discover a new constellation every night.",
"Jede Naht auf diesem Planeten wurde von Hand gestickt. Das sagt jedenfalls Bürgermeister Flicken.": "Every seam on this planet was stitched by hand. At least that's what Mayor Patches says.",
"Jede Schneeflocke hat sechs Arme. Weil jede einen etwas anderen Weg durch die Wolke nimmt, sind keine zwei genau gleich.": "Every snowflake has six arms. Because each one takes a slightly different path through the cloud, no two are exactly alike.",
"Jeder Dino hier hat unter dem Fuss eine Nummer. Die Nummer 1 ist leider verschwunden.": "Every dino here has a number under its foot. Sadly number 1 has disappeared.",
"Jeder Strichcode steht für eine Zahl. Die Kasse sucht damit im Computer den Namen und den Preis heraus.": "Every barcode stands for a number. The till uses it to look up the name and price in the computer.",
"Jeder erledigte Auftrag macht das Dorf schöner und bringt Dorf-Sterne.": "Every completed job makes the village more beautiful and brings village stars.",
"Jedes Buch hier hat einmal eine Geschichte erzählt. Manche haben ihre Seiten verloren – der Wind trägt sie über den ganzen Planeten.": "Every book here once told a story. Some have lost their pages – the wind carries them across the whole planet.",
