"Junge Schollen schwimmen wie normale Fische. Beim Erwachsenwerden wandert ein Auge auf die andere Seite, und sie legen sich flach auf den Boden.": "Young plaice swim like normal fish. As they grow up, one eye moves to the other side and they lie flat on the bottom.",
"Junge Spinnen „ballonieren“: Sie lassen Seidenfäden in den Wind und fliegen damit manchmal hunderte Kilometer weit – sogar übers Meer.": "Young spiders “balloon”: they let silk threads into the wind and sometimes fly hundreds of kilometres with them – even across the sea.",
