"Karauschen sind echte Überlebenskünstler: Im zugefrorenen Teich ohne Sauerstoff wandeln sie Zucker in Alkohol um und überstehen so monatelang. Die Rost-Karausche übersteht auf dem Schrott-Mond sogar Ölwechsel. Ein bisschen Rost gehört für sie zum Charakter.": "Crucian carp are true survival artists: in a frozen pond without oxygen they turn sugar into alcohol and survive for months. The rust crucian carp on the Scrap Moon even survives oil changes. A bit of rust is part of its character.",
"Karauschen überleben den Winter in sauerstoffarmem Wasser, indem sie Zucker ohne Sauerstoff zu Alkohol umbauen. Kein Scherz.": "Crucian carp survive winter in oxygen-poor water by turning sugar into alcohol without oxygen. No joke.",
"Karawane": "Caravan",
"Karawanen trugen seit Jahrtausenden Handelswaren durch die Wüste. Viele Oasen waren wichtige Treffpunkte zwischen Kulturen.": "Caravans have carried trade goods through the desert for thousands of years. Many oases were important meeting places between cultures.",
