"Karpfen haben Zähne – aber nicht im Maul, sondern tief im Schlund. Mit diesen Schlundzähnen zermahlen sie Muscheln und Pflanzen.": "Carp have teeth – but not in their mouth, deep in their throat. They grind shells and plants with these throat teeth.",
"Karpfen können über 40 Jahre alt werden. Man erkennt ihr Alter an Ringen auf den Schuppen, wie bei einem Baum.": "Carp can live over 40 years. You can tell their age from rings on their scales, like a tree.",
