"Katzen schlafen 12 bis 16 Stunden am Tag. Sie sparen so Energie für die Jagd.": "Cats sleep 12 to 16 hours a day. That saves energy for hunting.",
"Katzen schlafen gern auf warmen Geräten. Früher lagen sie oft auf den warmen Röhrenbildschirmen.": "Cats like sleeping on warm devices. They used to lie on warm tube screens a lot.",
