"Kaulquappen atmen mit Kiemen und verwandeln sich später in Frösche mit Lungen. Diese hier wächst dabei ein kleines Pilzhütchen.": "Tadpoles breathe with gills and later turn into frogs with lungs. This one grows a little mushroom cap along the way.",
"Kaulquappen atmen zuerst mit Kiemen. Nach einigen Wochen wachsen Beine, der Schwanz verschwindet – aus der Larve wird ein Frosch.": "Tadpoles breathe with gills at first. After a few weeks legs grow and the tail disappears – the larva becomes a frog.",
