"Kein Schneekristall gleicht dem anderen, weil jeder auf seinem Fall durch die Wolke andere Temperaturen erlebt. Dieser Barsch trägt das Muster als Tarnung unter dem Eis.": "No two snow crystals are alike, because each one goes through different temperatures on its way down through the cloud. This perch wears the pattern as camouflage under the ice.",
