"Kois sind Zuchtformen des Karpfens und können über 50 Jahre alt werden. In Japan gelten sie als Glücksbringer.": "Koi are bred forms of carp and can live over 50 years. In Japan they are considered lucky.",
"Kois sind Zuchtformen des Karpfens und können über 50 Jahre alt werden. Jede Fleckenzeichnung ist einzigartig wie ein Fingerabdruck. Im Labor sagt man: Wer einem Koi lange zusieht, vergisst, auf sein Handy zu schauen.": "Koi are bred forms of carp and can live over 50 years. Every spot pattern is unique like a fingerprint. In the lab they say: whoever watches a koi for a long time forgets to look at their phone.",
