"Kreuzspinnen spinnen jeden Tag ein neues Radnetz und fressen das alte auf, um die Seide wiederzuverwerten – Recycling-Profis! Spinnenseide ist, gemessen am Gewicht, stärker als Stahl. Ihr weisses Kreuz auf dem Rücken gab ihr den Namen.": "Garden spiders spin a new orb web every day and eat the old one to recycle the silk – recycling pros! For its weight, spider silk is stronger than steel. The white cross on its back gave it its German name.",
