"Kugelfisch": "Pufferfish",
"Kugelfische blasen sich bei Gefahr mit Wasser zu einer stacheligen Kugel auf. Eine japanische Art zeichnet mit ihren Flossen riesige Kreis-Kunstwerke in den Sand, um Weibchen zu beeindrucken. Das Museum hält das für die schönste Form von Landschaftsarchitektur.": "When in danger, pufferfish blow themselves up with water into a prickly ball. A Japanese species draws huge circular artworks in the sand with its fins to impress females. The museum thinks it's the most beautiful form of landscape architecture.",
"Kugelfische pumpen sich mit Wasser auf, wenn sie Angst haben. So passen sie Räubern nicht mehr ins Maul.": "Pufferfish pump themselves up with water when they're scared. Then they no longer fit into predators' mouths.",
"Kugelfische schlucken bei Gefahr blitzschnell Wasser und blasen sich zur stacheligen Kugel auf. Der Lüfter-Kugelfisch hat zusätzlich einen Ventilator auf dem Rücken, der das Kühlwasser umwälzt. Ohne ihn würde es im Rechenzentrum-Teich schnell stickig.": "When in danger, pufferfish gulp water in a flash and blow themselves up into a prickly ball. The fan pufferfish also has a fan on its back that circulates the cooling water. Without it the data-centre pond would quickly get stuffy.",
