"Libelle": "Dragonfly",
"Libellen fliegen seit über 300 Millionen Jahren. Sie können vorwärts, rückwärts und in der Luft stehen – kleine Hubschrauber mit Facettenaugen.": "Dragonflies have been flying for over 300 million years. They can fly forwards, backwards and hover – little helicopters with compound eyes.",
"Libellen gab es schon vor den Dinosauriern, manche Urzeit-Libellen hatten fast einen Meter Flügelspannweite. Ihre vier Flügel bewegen sie unabhängig voneinander und erwischen damit fast jede Mücke, die sie jagen. Die Larven leben jahrelang unter Wasser, bevor sie schlüpfen.": "Dragonflies existed before the dinosaurs; some prehistoric dragonflies had a wingspan of almost a metre. They move their four wings independently and catch almost every mosquito they hunt. The larvae live under water for years before they hatch.",
"Libellen gehören zu den schnellsten Insekten. Manche erreichen über 50 Kilometer pro Stunde und können sogar rückwärts fliegen.": "Dragonflies are among the fastest insects. Some reach over 50 kilometres per hour and can even fly backwards.",
"Libellen können mit ihren vier Flügeln unabhängig voneinander schlagen: vorwärts, rückwärts, seitwärts und in der Luft stehen.": "Dragonflies can beat their four wings independently: forwards, backwards, sideways and hovering in the air.",
"Libellen sind hervorragende Flieger mit vier unabhängig beweglichen Flügeln. Die Solar-Libelle der Korallen-Welt hat Solarzellen auf den Flügeln und lädt sich tagsüber über dem Meer auf. Abends hilft sie den Leuchtkorallen mit ein bisschen Strom aus.": "Dragonflies are excellent fliers with four independently moving wings. The solar dragonfly of Coral World has solar cells on its wings and charges up over the sea during the day. In the evening it helps the glowing corals out with a bit of power.",
"Libellenflügel": "Dragonfly wings",
"Libellenflügel sind so leicht und steif, dass Forschende sie für winzige Flugroboter nachbauen.": "Dragonfly wings are so light and stiff that researchers copy them for tiny flying robots.",
