"Magnetschwebe": "Maglev",
"Magnetschwebebahnen berühren die Schiene nicht. Starke Magnete lassen den Zug ein paar Zentimeter darüber schweben.": "Maglev trains don't touch the rail. Strong magnets make the train float a few centimetres above it.",
"Magnetstein": "Lodestone",
"Make kin, not babies. Hat mal jemand gesagt.": "Make kin, not babies. Someone once said.",
"Makrele": "Mackerel",
"Makrelen schwimmen ihr ganzes Leben lang ununterbrochen, weil sie keine Schwimmblase haben und sonst absinken würden. Ihre wellenförmigen Streifen tarnen sie im flackernden Licht unter der Wasseroberfläche. Faul sein ist für sie keine Option – schade eigentlich.": "Mackerel swim nonstop their whole lives because they have no swim bladder and would otherwise sink. Their wavy stripes camouflage them in the flickering light under the surface. Being lazy is not an option for them – a pity, really.",
"Mal-Atelier": "Painting studio",
"Malen": "Paint",
"Malen und Kunst. Du bist hier willkommen.": "Painting and art. You're welcome here.",
"Malen wir zusammen?": "Shall we paint together?",
"Mammut-Stosszahn": "Mammoth tusk",
"Man hat dich bewusstlos neben einer abgestürzten Rakete gefunden.": "You were found unconscious next to a crashed rocket.",
"Man misst, wie hoch das Wasser im Becher steht. Ein Millimeter heisst: ein Liter Regen auf jedem Quadratmeter.": "You measure how high the water stands in the cup. One millimetre means: one litre of rain on every square metre.",
"Man nennt es auch das „Wood Wide Web“.": "It's also called the “Wood Wide Web”.",
"Man sagt, auf anderen Planeten liegen leuchtende Erinnerungs-Splitter. Vielleicht finden wir so heraus, wer du warst …": "They say glowing memory splinters lie on other planets. Maybe that's how we'll find out who you were …",
"Manche Falter haben eine innere Uhr, die an die Sonne gekoppelt ist. Monarchfalter finden damit auf ihrer tausende Kilometer langen Reise den Weg.": "Some butterflies have an inner clock linked to the sun. Monarch butterflies use it to find their way on their journey of thousands of kilometres.",
"Manche Falter überwintern als erwachsene Tiere und frieren dabei fast ein. Sie bilden Frostschutzmittel im Körper, ähnlich wie Autos.": "Some moths spend the winter as adults and almost freeze. They make antifreeze in their bodies, a bit like cars.",
"Manche Fische haben Muster, die wie Schrift aussehen – etwa der Arabische Kaiserfisch, auf dessen Schwanz man Zeichen zu erkennen meinte.": "Some fish have patterns that look like writing – such as the Arabian angelfish, on whose tail people thought they could see letters.",
"Manche Fische in Polarmeeren haben Frostschutz-Eiweisse im Blut, die Eiskristalle am Wachsen hindern. So bleiben sie bei Minusgraden flüssig – quasi Winterreifen von innen.": "Some fish in polar seas have antifreeze proteins in their blood that stop ice crystals from growing. That way they stay liquid below zero – winter tyres on the inside, so to speak.",
"Manche Fische können ihre Farbe ändern. Sie haben dafür besondere Zellen in der Haut, die Farbstoff verteilen oder zusammenziehen.": "Some fish can change their colour. They have special cells in their skin that spread out or pull together pigment.",
"Manche Karpfen fressen herabfallende Blüten und Insekten von der Wasseroberfläche.": "Some carp eat blossoms and insects that fall onto the water's surface.",
"Manche Käfer klopfen mit dem Kopf gegen Holz, um Partner zu finden. Weil das nachts wie eine Uhr tickt, heisst einer von ihnen Totenuhr.": "Some beetles knock their heads against wood to find a partner. Because it ticks like a clock at night, one of them is called the deathwatch beetle.",
"Manche Käfer schimmern golden, obwohl kein Gold in ihnen ist. Winzige Schichten in ihrem Panzer werfen das Licht zurück.": "Some beetles shimmer golden even though there's no gold in them. Tiny layers in their shell reflect the light.",
"Manche Käfer spritzen bei Gefahr übelriechende Flüssigkeit. Der Bombardierkäfer schiesst sie sogar knallend und kochend heiss heraus.": "Some beetles spray a smelly liquid when in danger. The bombardier beetle even shoots it out with a bang, boiling hot.",
"Manche Nachtfalter können Ultraschall-Klicks erzeugen und damit Fledermäuse verwirren, die sie mit ihrem Echo-Ortungssystem jagen.": "Some moths can make ultrasonic clicks to confuse bats that hunt them with their echolocation.",
"Manche Pilze und Algen leuchten im Dunkeln. Man nennt das Biolumineszenz – lebendes Licht.": "Some mushrooms and algae glow in the dark. This is called bioluminescence – living light.",
"Manche Pilze, Schnecken und Tiefseetiere leuchten selbst – das nennt man Biolumineszenz.": "Some mushrooms, snails and deep-sea animals glow by themselves – this is called bioluminescence.",
"Manche Quallen leuchten durch ein Eiweiss namens GFP. Forschende nutzen es heute, um Zellen im Mikroskop sichtbar zu machen.": "Some jellyfish glow thanks to a protein called GFP. Researchers use it today to make cells visible under the microscope.",
"Manche Samen haben Flügel und drehen sich im Wind wie ein Hubschrauber. So fliegen sie weit vom Baum weg.": "Some seeds have wings and spin in the wind like a helicopter. That way they fly far away from the tree.",
"Manche Tiefseetiere leuchten selbst. Dieses Leuchten heisst Biolumineszenz und entsteht durch eine chemische Reaktion im Körper.": "Some deep-sea animals glow by themselves. This glow is called bioluminescence and comes from a chemical reaction in the body.",
"Manche Tiere – Brieftauben, Meeresschildkröten – spüren das Magnetfeld der Erde und finden damit ihren Weg.": "Some animals – homing pigeons, sea turtles – sense the Earth's magnetic field and use it to find their way.",
"Mango-Markt": "Mango market",
"Mangroven": "Mangroves",
"Mantarochen gehören zu den intelligentesten Fischen und erkennen sich vielleicht sogar im Spiegel. Sie filtern winziges Plankton aus dem Wasser und gleiten dabei wie Vögel. Der Solar-Rochen trägt Solarzellen auf den Flügeln und teilt seinen Strom gern mit Korallen-Cyborgs.": "Manta rays are among the most intelligent fish and may even recognise themselves in a mirror. They filter tiny plankton out of the water and glide like birds while doing so. The solar ray carries solar cells on its wings and likes to share its power with coral cyborgs.",
"Margarete Marginal": "Margarete Margin",
"Marienkäfer": "Ladybird",
"Marienkäfer fressen Blattläuse – bis zu 150 am Tag. Stadtgärtner:innen lieben sie deshalb.": "Ladybirds eat aphids – up to 150 a day. That's why city gardeners love them.",
"Marienkäfer sondern bei Gefahr eine bittere gelbe Flüssigkeit aus den Beinen ab. Vögel lernen schnell: Rot mit Punkten schmeckt scheusslich.": "When in danger, ladybirds release a bitter yellow liquid from their legs. Birds learn quickly: red with spots tastes horrible.",
