"Maulwürfe graben bis zu 20 Meter Gang am Tag. Sie sehen kaum etwas, aber ihre Nase und die Tasthaare an der Schnauze sind super empfindlich.": "Moles dig up to 20 metres of tunnel a day. They can hardly see, but their nose and the whiskers on their snout are super sensitive.",
