"Meeres-Wasserläufer": "Sea skater",
"Meeres-Wasserläufer sind die einzigen Insekten, die auf dem offenen Ozean leben – tausende Kilometer vom Land entfernt. Winzige wasserabweisende Härchen lassen sie auf der Oberfläche flitzen. Ihre Eier kleben sie an Treibgut – heute leider oft an Plastikmüll.": "Sea skaters are the only insects that live on the open ocean – thousands of kilometres from land. Tiny water-repellent hairs let them dart across the surface. They glue their eggs to driftwood – today sadly often to plastic rubbish.",
"Meeresschildkröte": "Sea turtle",
"Meeresschildkröten kehren zum Eierlegen an den Strand zurück, an dem sie selbst geschlüpft sind – nach bis zu 30 Jahren!": "Sea turtles return to lay eggs on the beach where they themselves hatched – after up to 30 years!",
"Meeresschildkröten verwechseln treibende Plastiktüten oft mit Quallen, ihrem Lieblingsessen – und werden davon krank. Jede eingesammelte Tüte kann also ein Leben retten. Das Museum nimmt sie trotzdem auf: als Mahnmal mit Henkeln.": "Sea turtles often mistake drifting plastic bags for jellyfish, their favourite food – and get sick from them. So every bag collected can save a life. The museum takes it anyway: as a memorial with handles.",
"Mega-Spielhalle": "Mega arcade",
"Mehr": "More",
"Mehr Aufträge erledigen, Blumen pflanzen und Bewohner:innen glücklich machen – dann steigen die Sterne!": "Complete more jobs, plant flowers and make residents happy – then the stars go up!",
"Mehr weiss ich auch nicht. Die Splitter werden es zeigen.": "That's all I know. The splinters will show us.",
