"Mistkäfer rollen ihre Kugel nachts schnurgerade. Sie orientieren sich dabei an der Milchstrasse am Himmel.": "Dung beetles roll their ball dead straight at night. They use the Milky Way in the sky to find their direction.",
"Mit ": "With ",
"Mit Schrotti reden": "Talk to Scrappy",
"Mit Siegeln wurden Briefe verschlossen und beglaubigt. Wer das Siegel brach, konnte das nicht verbergen.": "Seals were used to close and certify letters. Whoever broke the seal couldn't hide it.",
"Mit dem grossen Schlüssel kannst du sie wieder aufziehen. Sie laufen dann ihre alte Runde – und ticken ganz zufrieden.": "With the big key you can wind them up again. Then they walk their old rounds – and tick very contentedly.",
"Mit dem tragbaren Kassettenspieler konnte man 1979 zum ersten Mal Musik überall mit sich herumtragen. Wenn die Batterien schwach wurden, leierte die Musik ganz langsam. Die Kopfhörer mit den orangen Schaumpolstern sind heute Kult.": "With the portable cassette player, in 1979 people could carry music around everywhere for the first time. When the batteries got weak, the music dragged very slowly. The headphones with the orange foam pads are cult today.",
