"Monarchfalter": "Monarch butterfly",
"Monarchfalter wandern jedes Jahr bis zu 4000 Kilometer von Kanada nach Mexiko – und keiner von ihnen hat den Weg je gelernt, denn die Reise dauert mehrere Generationen. Ihre Raupen fressen giftige Seidenpflanzen und werden dadurch selbst ungeniessbar. Kluges Buffet!": "Monarch butterflies migrate up to 4000 kilometres every year from Canada to Mexico – and none of them ever learned the way, because the journey takes several generations. Their caterpillars eat poisonous milkweed and so become inedible themselves. A clever buffet!",
