"Mondfisch": "Sunfish",
"Mondfische sind die schwersten Knochenfische der Welt und können über zwei Tonnen wiegen. Sie fressen vor allem Quallen und legen sich zum Aufwärmen flach an die Wasseroberfläche. Ein Schwanz ist ihnen nie gewachsen – sie finden, sie brauchen keinen.": "Ocean sunfish are the heaviest bony fish in the world and can weigh over two tonnes. They mostly eat jellyfish and lie flat at the surface to warm up. They never grew a tail – they think they don't need one.",
