"Motten orientieren sich eigentlich am Mondlicht. Strassenlaternen verwirren sie – dunklere, warme Lampen helfen ihnen.": "Moths actually navigate by moonlight. Street lamps confuse them – darker, warm lamps help them.",
"Motten orientieren sich nachts am Mond. Eine Lampe ist so nah, dass sie die Motten im Kreis herumführt.": "Moths navigate by the moon at night. A lamp is so close that it leads the moths round in circles.",
"Motten orientieren sich nachts am Mond. Künstliches Licht verwirrt sie – darum kreisen sie um Lampen.": "Moths navigate by the moon at night. Artificial light confuses them – that's why they circle lamps.",
