"Männliche Winkerkrabben haben eine riesige Schere, mit der sie Weibchen zuwinken und Rivalen beeindrucken. Die Schere ist oft so schwer wie der ganze restliche Körper. Beim Fressen sieben sie winzige Algen aus dem Sand und hinterlassen kleine Sandkügelchen.": "Male fiddler crabs have a giant claw they use to wave at females and impress rivals. The claw is often as heavy as the whole rest of the body. When eating, they sift tiny algae out of the sand and leave little sand balls behind.",
"Mäuse verständigen sich oft mit Tönen, die so hoch sind, dass Menschen sie gar nicht hören können.": "Mice often communicate with sounds so high that humans can't hear them at all.",
