"Mückenlarve": "Mosquito larva",
"Mückenlarven hängen unter der Wasseroberfläche und atmen durch ein kleines Rohr am Hinterende. Bei Gefahr zappeln sie blitzschnell nach unten.": "Mosquito larvae hang under the water's surface and breathe through a little tube at their rear end. When in danger they wriggle down in a flash.",
