"Nach Hause": "Home",
"Nach jedem Regen spannt sich ein Regenbogen. Wer schnell ist, findet an seinem Ende einen Topf voller Splitter.": "After every rain a rainbow appears. Whoever is quick finds a pot full of splinters at its end.",
