"Nachtfalter fliegen zu Lampen, weil sie sich eigentlich am Mond orientieren. Helle Lampen bringen ihren Kompass durcheinander.": "Moths fly to lamps because they actually navigate by the moon. Bright lamps mix up their compass.",
