"Nachtigallen singen über 200 verschiedene Strophen. Sie singen oft nachts, weil ihr Lied dann weiter trägt und weniger andere Vögel dazwischen zwitschern.": "Nightingales sing over 200 different verses. They often sing at night because their song carries further and fewer other birds chirp over it.",
"Nachtkommode": "Bedside cabinet",
"Nachts": "At night",
"Nachts schweben die Buchstaben aus den Büchern und tanzen um die Lampen. Ganz leise, damit niemand aufwacht.": "At night the letters float out of the books and dance around the lamps. Very quietly, so nobody wakes up.",
"Nachts öffnet sich manchmal ein Zeitriss am Vulkan. Wer hindurchgeht, sieht, wie alles einmal war.": "At night a time rift sometimes opens at the volcano. Whoever walks through sees how everything once was.",
