"Neonfische schillern durch winzige Kristalle in der Haut, die das Licht spiegeln – es ist Struktur, keine Farbe.": "Neon fish shimmer because of tiny crystals in their skin that reflect light – it's structure, not colour.",
"Neonsalmler": "Neon tetra",
"Neonsalmler stammen aus dunklen Urwaldflüssen in Südamerika. Ihr blauer Streifen spiegelt Licht so, dass sich der Schwarm im trüben Wasser wiederfindet. Auf dem Schrott-Mond fühlen sie sich im warmen, leicht leuchtenden Kühlwasser sofort zu Hause.": "Neon tetras come from dark jungle rivers in South America. Their blue stripe reflects light so the shoal can find each other in murky water. On the Scrap Moon they feel at home right away in the warm, faintly glowing cooling water.",
