"Oktopusse haben drei Herzen, blaues Blut und denken zum Teil mit ihren Armen: Zwei Drittel ihrer Nervenzellen stecken in den Tentakeln. Die Philosophin Donna Haraway nennt unsere Zeit gern „Chthuluzän“ – nach tentakeligen Wesen, die alles mit allem verknüpfen. Dieser hier findet das sehr schmeichelhaft.": "Octopuses have three hearts, blue blood and partly think with their arms: two thirds of their nerve cells are in the tentacles. The philosopher Donna Haraway likes to call our time the “Chthulucene” – after tentacled beings that connect everything with everything. This one finds that very flattering.",
