"Piko: Ei öffnen (Tab)": "Piko: open the egg (Tab)",
"Pillendreher orientieren sich an der Milchstrasse, um ihre Kugel geradeaus zu rollen. Sie waren im alten Ägypten heilig.": "Scarab beetles use the Milky Way to roll their ball straight ahead. They were sacred in ancient Egypt.",
