"Pilzbaum": "Mushroom tree",
"Pilze bilden unterirdische Netzwerke aus Fäden, das Myzel. Bäume tauschen darüber Nährstoffe aus – manche nennen es das Wood Wide Web.": "Fungi form underground networks of threads, the mycelium. Trees exchange nutrients through it – some call it the Wood Wide Web.",
"Pilze leben oft in Symbiose mit anderen Lebewesen. Flechten zum Beispiel sind Pilz und Alge zugleich – ein Paradebeispiel für Make Kin.": "Fungi often live in symbiosis with other living things. Lichens, for example, are fungus and alga at the same time – a prime example of Make Kin.",
"Pilze sind weder Pflanzen noch Tiere – sie bilden ein eigenes Reich. Unter der Erde verbindet ihr Geflecht ganze Wälder.": "Fungi are neither plants nor animals – they form a kingdom of their own. Underground their network connects whole forests.",
"Pilze wachsen um ihn herum.": "Mushrooms grow around it.",
"Pilze waren unter den ersten Lebewesen an Land. Riesige Pilze namens Prototaxites wurden vor 400 Millionen Jahren bis zu 8 Meter hoch – höher als die Bäume damals.": "Fungi were among the first living things on land. Giant fungi called Prototaxites grew up to 8 metres tall 400 million years ago – taller than the trees back then.",
