"Pinguine können nicht fliegen, aber unter Wasser „fliegen“ sie mit ihren Flügeln. Kaiserpinguine tauchen über 500 Meter tief.": "Penguins can't fly, but under water they “fly” with their wings. Emperor penguins dive over 500 metres deep.",
"Pinguine sind Vögel, die unter Wasser fliegen. Dieser kleine Fisch hat sich ihre Farben abgeschaut: dunkel von oben, hell von unten – so ist er von oben und unten schwer zu sehen.": "Penguins are birds that fly under water. This little fish copied their colours: dark from above, light from below – that makes it hard to see from above and below.",
