"Piranhas haben einen schlimmen Ruf, sind aber eher scheu – viele Arten fressen sogar Früchte und Samen, die ins Wasser fallen. Der Chrom-Piranha knabbert Rost von alten Rohren und hält so die Kühlkreisläufe frei. Ein Hausmeister mit Zähnen.": "Piranhas have a bad reputation but are rather shy – many species even eat fruit and seeds that fall into the water. The chrome piranha nibbles rust off old pipes and keeps the cooling circuits clear. A caretaker with teeth.",
"Piranhas sind meist scheue Schwarmfische und fressen auch Früchte und Samen. Angriffe auf Menschen sind sehr selten.": "Piranhas are mostly shy shoaling fish and also eat fruit and seeds. Attacks on humans are very rare.",
