"Quallen bestehen zu 95 Prozent aus Wasser und haben weder Gehirn noch Herz – und schwimmen trotzdem seit 500 Millionen Jahren durch die Meere. Die Leuchtröhren-Qualle ist aus alten Glühbirnen geschlüpft. Ihr Glühfaden brennt mit Abwärme aus dem Kühlwasser.": "Jellyfish are 95 percent water and have neither brain nor heart – and still they've been swimming through the seas for 500 million years. The neon-tube jellyfish hatched from old light bulbs. Its filament burns with waste heat from the cooling water.",
"Quallen bestehen zu 98 Prozent aus Wasser. Sie haben weder Gehirn noch Herz, aber ein Nervennetz im ganzen Körper.": "Jellyfish are 98 percent water. They have neither brain nor heart, but a nerve net throughout their whole body.",
"Quallen schwimmen durch Rückstoss: Sie ziehen ihren Schirm zusammen und pressen Wasser heraus. So bewegen sie sich schon seit 500 Millionen Jahren.": "Jellyfish swim by jet propulsion: they squeeze their bell and push water out. They've been moving like this for 500 million years.",
