"Raupen fressen ohne Pause, um genug Energie für ihre Verwandlung zu sammeln. Die Kabel-Raupe knabbert sich durch Elektroschrott und sortiert dabei Kupfer, Plastik und Gold. Aus ihrem Kokon schlüpft – das weiss noch niemand. Das Museum wartet gespannt.": "Caterpillars eat nonstop to gather enough energy for their transformation. The cable caterpillar nibbles its way through electronic scrap, sorting copper, plastic and gold as it goes. What hatches from its cocoon – nobody knows yet. The museum is waiting eagerly.",
