"Regenbogenforellen brauchen kühles, sauberes Wasser mit viel Sauerstoff. Die Chip-Forelle trägt einen winzigen Sensor, der die Wasserqualität misst – Forschende nutzen echte Tiere wie Muscheln tatsächlich als lebende Messgeräte. Tier, Maschine, Umweltamt: alles in einem Fisch.": "Rainbow trout need cool, clean water with lots of oxygen. The chip trout carries a tiny sensor that measures water quality – researchers really do use animals like mussels as living measuring devices. Animal, machine, environment agency: all in one fish.",
