"Regenwürmer fressen Erde und lockern sie dabei auf. Ein Wurm kann über die Hälfte seines Gewichts am Tag verdauen.": "Earthworms eat soil and loosen it up. A worm can digest over half its weight a day.",
"Regenwürmer fressen jeden Tag etwa ihr halbes Körpergewicht an Erde und verrotteten Pflanzen und machen daraus fruchtbaren Humus. Sie lockern den Boden, damit Wasser und Wurzeln hineinkommen. Ohne sie wäre der Kompost-Planet einfach nur ein Haufen.": "Earthworms eat about half their body weight in soil and rotted plants every day and turn it into fertile humus. They loosen the soil so water and roots can get in. Without them the Compost Planet would just be a heap.",
