"Röhrenfernseher": "Tube TV",
"Röhrenfernseher mit Konsole": "Tube TV with console",
"Röhrenfernseher schossen Elektronen auf eine leuchtende Glasfläche – und waren deshalb tief und schwer wie ein Umzugskarton voller Bücher. Im Glas steckt viel Blei, deshalb dürfen sie nie einfach auf den Müll. Auf dem Schrott-Mond dienen sie als gemütliche Höhlen für Pixel-Falter.": "Tube TVs shot electrons at a glowing glass surface – which is why they were as deep and heavy as a moving box full of books. The glass contains a lot of lead, so they must never simply go in the bin. On the Scrap Moon they serve as cosy caves for pixel moths.",
