"Schleien leben in ruhigen, schlammigen Teichen und wurden früher „Doktorfisch“ genannt, weil ihr Schleim angeblich andere Fische heilt. Die Pilz-Schleie trägt Myzel auf der Haut und verbindet so Teich und Waldboden. Pilze sind die Internetkabel der Natur – nur viel älter.": "Tench live in calm, muddy ponds and used to be called “doctor fish” because their slime supposedly heals other fish. The mushroom tench carries mycelium on its skin and so connects the pond with the forest floor. Fungi are nature's internet cables – just much older.",
