"Schnecken haben eine Raspelzunge mit tausenden winzigen Zähnchen. Damit schaben sie Algen und Pflanzen ab – man kann es manchmal richtig hören.": "Snails have a rasping tongue with thousands of tiny teeth. They use it to scrape off algae and plants – sometimes you can really hear it.",
