"Stichlings-Männchen bauen im Frühling kunstvolle Nester aus Pflanzenfasern und bewachen die Eier ganz allein. Dabei färbt sich ihre Kehle leuchtend rot. Der Moos-Stichling vom Kompost-Planeten lässt sich gleich ein kleines Moospolster auf dem Rücken wachsen.": "In spring, male sticklebacks build elaborate nests from plant fibres and guard the eggs all on their own. Their throat turns bright red while doing it. The moss stickleback of the Compost Planet even grows a little moss cushion on its back.",
