"Trilobiten krabbelten fast 300 Millionen Jahre über den Meeresboden. Ihre Augen bestanden aus Kalkkristallen – die ältesten Linsenaugen, die wir kennen.": "Trilobites crawled over the sea floor for almost 300 million years. Their eyes were made of calcite crystals – the oldest lens eyes we know.",
"Trilobiten krabbelten schon vor über 500 Millionen Jahren über den Meeresboden – lange bevor es Fische mit Kiefern gab. Sie hatten einige der ältesten Augen der Welt, mit Linsen aus Kalkstein. Ihr Körper war in drei Längsteile gegliedert, daher der Name.": "Trilobites crawled over the sea floor over 500 million years ago – long before there were fish with jaws. They had some of the oldest eyes in the world, with lenses made of limestone. Their body was divided into three lengthwise parts, hence the name.",
