"Unser Planet lebt vom Kreislauf: Was verwelkt, wird Erde, und aus Erde wächst Neues.": "Our planet lives from the cycle: what wilts becomes soil, and new things grow from soil.",
"Unser Planet wurde aus einem einzigen, riesigen Blatt gefaltet. Irgendwo muss noch die erste Falte sein.": "Our planet was folded from a single giant sheet. The first fold must still be somewhere.",
"Unser Tal ist sehr, sehr alt. Die Dinos waren zuerst hier, wir sind nur zu Besuch.": "Our valley is very, very old. The dinos were here first, we're only visiting.",
"Unsere Grenze war Mensch / Tier. Wir sind für sie verantwortlich, weil wir sie gewählt haben und nicht geerbt.": "Our border was human / animal. We are responsible for it because we chose it and didn't inherit it.",
"Unsere Grenze war Organismus / Maschine. Wir sind für sie verantwortlich, weil wir entscheiden, ob Technik hilft oder normiert.": "Our border was organism / machine. We are responsible for it because we decide whether technology helps or normalises.",
"Unsere Grenze war physisch / nichtphysisch. Wir sind für sie verantwortlich, weil wir Beben spüren wollen, die wir nicht verursacht haben.": "Our border was physical / non-physical. We are responsible for it because we want to feel tremors we didn't cause.",
"Unsere Grenze war öffentlich / privat. Wir sind für sie verantwortlich, weil wir den Fremden selbst in die Küche bestellt haben.": "Our border was public / private. We are responsible for it because we invited the stranger into the kitchen ourselves.",
"Unsere Inseln schweben, seit ein Riesenwal das Meer in Wolken verwandelt hat. So erzählen es die Alten.": "Our islands have floated ever since a giant whale turned the sea into clouds. That's what the old ones say.",
"Unsere Oasen teilen wir gerecht – Tiere zuerst!": "We share our oases fairly – animals first!",
"Unsere Taxis bringen dich überallhin. Einfach am Taxistand einsteigen!": "Our taxis take you anywhere. Just get in at the taxi rank!",
"Unter unseren Füssen verbindet ein riesiges Pilzgeflecht alles miteinander.": "Under our feet a huge fungal network connects everything with everything.",
