"Verschlossen. Auf dem Deckel steht: KOKON WARTUNG · 31.12.1999 23:59": "Locked. The lid says: KOKON MAINTENANCE · 31.12.1999 23:59",
"Verschneites Bäumchen": "Snowy little tree",
"Versteinerter Kot verrät, was Dinos gegessen haben: Pflanzenreste, Knochensplitter, sogar Parasiten. Forschende nennen das liebevoll Koprolithen.": "Fossilised poo reveals what dinos ate: plant remains, bone splinters, even parasites. Researchers fondly call them coprolites.",
"Versteinertes Ei": "Fossilised egg",
"Verwandelt die Umgebung in eine Landschaft eines besuchten Planeten.": "Turns the surroundings into a landscape from a visited planet.",
"Vibrafon": "Vibraphone",
"Vichy-Karo": "Gingham check",
"Viele Computer speicherten das Jahr nur mit zwei Ziffern. Man befürchtete, dass sie das Jahr 2000 mit 1900 verwechseln. Das nannte man das «Jahr-2000-Problem».": "Many computers stored the year with only two digits. People feared they would mix up the year 2000 with 1900. This was called the “Year 2000 problem”.",
"Viele Falter haben Augenflecken auf den Flügeln. Sie erschrecken Vögel, weil sie wie die Augen eines grösseren Tieres aussehen.": "Many butterflies have eyespots on their wings. They scare birds because they look like the eyes of a bigger animal.",
"Viele Feste auf der Welt richten sich nach dem Mond. Ein Mondmonat dauert etwa 29,5 Tage – von Vollmond zu Vollmond.": "Many festivals around the world follow the moon. A lunar month lasts about 29.5 days – from full moon to full moon.",
"Viele Fische haben ein «Seitenlinienorgan». Damit spüren sie kleinste Wasserbewegungen, fast wie ein Radar.": "Many fish have a “lateral line”. With it they sense the tiniest water movements, almost like radar.",
"Viele Fische haben silberne Schuppen. Sie spiegeln das Licht und machen den Fisch im Wasser fast unsichtbar.": "Many fish have silver scales. They reflect the light and make the fish almost invisible in the water.",
"Viele Fische machen Geräusche: Umberfische trommeln mit ihrer Schwimmblase so laut, dass man sie über Wasser hört.": "Many fish make noises: drum fish drum with their swim bladder so loudly that you can hear them above water.",
"Viele Fische orientieren sich nachts am Mondlicht. Manche Riff-Fische laichen nur in bestimmten Mondnächten.": "Many fish navigate by moonlight at night. Some reef fish only spawn on certain moonlit nights.",
"Viele Grossstädte wuchsen auf ehemaligen Sümpfen oder Inseln. Manhattan etwa hatte früher über 50 Hügel, die abgetragen wurden.": "Many big cities grew on former swamps or islands. Manhattan, for example, once had over 50 hills that were levelled.",
"Viele Käfer glänzen, weil ihr Panzer aus vielen dünnen Schichten besteht. Das Licht wird an jeder Schicht ein bisschen zurückgeworfen.": "Many beetles shine because their shell is made of many thin layers. Light is reflected a little at every layer.",
"Viele Käfer haben harte Deckflügel. Darunter liegen die dünnen Flügel, mit denen sie wirklich fliegen.": "Many beetles have hard wing cases. Underneath are the thin wings they really fly with.",
"Viele Käfer sind nachtaktiv und orientieren sich an Mond und Sternen. Der Mondkäfer vom Sporen-Mond sammelt dabei Mondlicht in seinem Panzer.": "Many beetles are active at night and navigate by the moon and stars. The moon beetle from the Spore Moon collects moonlight in its shell while doing so.",
"Viele Käfer überwintern unter Steinen oder Rinde. Sie senken ihren Stoffwechsel so weit ab, dass sie monatelang ohne Nahrung auskommen.": "Many beetles spend the winter under stones or bark. They slow their metabolism down so far that they can go months without food.",
"Viele Plastikspielzeuge werden im Spritzguss gemacht: Heisser, flüssiger Kunststoff wird in eine Metallform gepresst und kühlt dort ab.": "Many plastic toys are made by injection moulding: hot, liquid plastic is pressed into a metal mould and cools there.",
"Viele Quallen leuchten selbst: Biolumineszenz. Im dunklen Polarwasser kann Licht Beute anlocken oder Feinde erschrecken.": "Many jellyfish glow by themselves: bioluminescence. In dark polar water, light can lure prey or scare enemies.",
"Viele Tiere spüren das Magnetfeld der Erde: Zugvögel, Meeresschildkröten, sogar manche Bakterien richten sich danach aus.": "Many animals sense the Earth's magnetic field: migrating birds, sea turtles, even some bacteria line up with it.",
"Viele Welse sind nachtaktiv und finden Futter mit ihren Barteln statt mit den Augen.": "Many catfish are active at night and find food with their whiskers instead of their eyes.",
"Viele alte Kulturen hatten mehrere Kalender gleichzeitig: einen für die Jahreszeiten, einen für Rituale. Sie liefen ineinander wie Zahnräder.": "Many ancient cultures had several calendars at once: one for the seasons, one for rituals. They ran into each other like gears.",
