"Von: ": "From: ",
"Vor 300 Millionen Jahren lebte die Riesenlibelle Meganeura. Ihre Flügel waren so breit wie ein ausgestreckter Arm.": "300 million years ago the giant dragonfly Meganeura lived. Its wings were as wide as an outstretched arm.",
"Vor 66 Millionen Jahren schlug ein etwa zehn Kilometer grosser Asteroid in Mexiko ein. Staub verdunkelte die Sonne, und die meisten Dinos starben aus – nur die Vögel nicht.": "66 million years ago an asteroid about ten kilometres wide hit Mexico. Dust darkened the sun and most dinos died out – but not the birds.",
"Vor dem Füller schrieb man mit Gänsefedern, die man mit einem kleinen Messer spitzte – dem Federmesser. Daher kommt der Name „Taschenmesser“ für kleine Klappmesser.": "Before fountain pens, people wrote with goose quills that they sharpened with a small knife – the penknife. That's where the name for small folding knives comes from.",
