"Wanzen erkennt man an ihrem schildförmigen Rücken und dem Saugrüssel. Die Kondensator-Wanze speichert tagsüber Ladung und gibt sie nachts in winzigen Funken ab. Anfassen kitzelt – aber nur ein bisschen.": "You can recognise bugs by their shield-shaped back and their sucking beak. The capacitor bug stores charge during the day and releases it in tiny sparks at night. Touching it tickles – but only a little.",
"Wanzen haben einen Saugrüssel und riechen oft stark, um Feinde abzuschrecken. Viele sind aber harmlose Pflanzensauger.": "Bugs have a sucking beak and often smell strongly to scare off enemies. But many are harmless plant-suckers.",
