"Warum können Roboter nie lügen? Weil sie sonst einen Kurzschluss im Gewissen kriegen!": "Why can robots never lie? Because they'd get a short circuit in their conscience!",
"Warum war das Schaf so entspannt? Es hatte alles im Wollgriff.": "Why was the sheep so relaxed? It had everything under wool control.",
"Was bedeutet das Zeichen @ in einer E-Mail-Adresse?": "What does the @ sign in an email address mean?",
"Was darf's sein? Wir kaufen auch alles, was du fängst!": "What can I get you? We also buy everything you catch!",
