"Waschbären „waschen\" ihr Futter gar nicht: Sie tasten es im Wasser ab, weil ihre Pfoten nass noch empfindlicher sind.": "Raccoons don't actually “wash” their food: they feel it in the water because their paws are even more sensitive when wet.",
