"Wasserläufer": "Pond skater",
"Wasserläufer haben wasserabweisende Härchen an den Füssen. Die Wasseroberfläche trägt sie wie eine dünne Haut.": "Pond skaters have water-repellent hairs on their feet. The water's surface carries them like a thin skin.",
