"Weil Glätte zu teuer ist": "Because smoothness is too expensive",
"Weil es weltweit weniger Insekten gibt, bauen Forschende tatsächlich winzige Drohnen, die Blüten bestäuben sollen. Aber keine Maschine kann eine Wiese voller Bienen, Hummeln und Schwebfliegen ersetzen. Die Nano-Drohne sieht das genauso und hilft lieber beim Zählen.": "Because there are fewer insects worldwide, researchers really are building tiny drones meant to pollinate flowers. But no machine can replace a meadow full of bees, bumblebees and hoverflies. The nano drone sees it the same way and would rather help with counting.",
"Weinbergschnecke": "Roman snail",
"Weinbergschnecken können über 20 Jahre alt werden. Ihr Haus wächst mit – es wird am Rand immer weiter angebaut.": "Roman snails can live over 20 years. Their house grows with them – it keeps being built on at the rim.",
"Weinbergschnecken tragen ihr Haus ein Leben lang mit sich und können über 20 Jahre alt werden. Ihr Schleim ist so gut, dass sie damit über eine Rasierklinge kriechen können, ohne sich zu verletzen. Im Kompost zerkleinern sie welke Blätter zu neuer Erde.": "Roman snails carry their house with them all their life and can live over 20 years. Their slime is so good they can crawl over a razor blade without getting hurt. In the compost they break down wilted leaves into new soil.",
"Weinglas": "Glass",
"Weinhähnchen": "Italian tree cricket",
"Weisst du wenigstens noch deinen Namen?": "Do you at least remember your name?",
"Weisst du, wie spät es ist? Ich schon. Immer.": "Do you know what time it is? I do. Always.",
"Weiter": "Next",
"Weiterfliegen": "Fly on",
