"Wels": "Catfish",
"Welse ertasten und schmecken mit ihren Barteln. So finden sie Futter auch im trüben Wasser.": "Catfish feel and taste with their whiskers. That way they find food even in murky water.",
"Welse schmecken mit dem ganzen Körper: Auf ihrer Haut sitzen Zehntausende Geschmacksknospen.": "Catfish taste with their whole body: tens of thousands of taste buds sit on their skin.",
"Welse sind die grössten Süsswasserfische Europas und können über zwei Meter lang werden. Mit ihren Barteln schmecken und tasten sie im trüben Wasser. Sie sind nachts unterwegs und räumen den Grund auf – eine Art schwimmende Kompost-Crew.": "Wels catfish are the biggest freshwater fish in Europe and can grow over two metres long. They taste and feel in murky water with their whiskers. They're out at night tidying the bottom – a kind of swimming compost crew.",
"Welse spüren mit ihren Barteln Geschmack – ihr ganzer Körper ist mit Geschmacksknospen bedeckt. Dieser hier hat sich zusätzlich einen Wintermantel wachsen lassen.": "Catfish sense taste with their whiskers – their whole body is covered with taste buds. This one has also grown itself a winter coat.",
"Welt geleert": "World emptied",
"Welt leeren": "Empty the world",
"Welt sichern": "Back up the world",
"Weltempfänger": "World receiver",
"Wendigkeit": "Agility",
"Wenn alle sechs wieder wach sind, spielt das Glockenspiel im Turm. Das haben wir seit hundert Jahren nicht mehr gehört.": "When all six are awake again, the glockenspiel in the tower plays. We haven't heard it for a hundred years.",
"Wenn die ganze Tauschkette geschafft ist, steigen die Himmelslaternen auf. Das sieht man von allen Planeten aus.": "When the whole trading chain is complete, the sky lanterns rise. You can see it from every planet.",
"Wenn dir etwas nicht gefällt: Im Labor können wir Teile austauschen. Nur eine kleine Operation!": "If there's something you don't like: in the lab we can swap parts. Just a small operation!",
"Wenn du Bäume schüttelst, fällt manchmal Obst runter. Und manchmal Wespen.": "When you shake trees, fruit sometimes falls down. And sometimes wasps.",
"Wenn du oben auf einer Pusteblume stehst und springst, trägt dich der Wind weit übers Land.": "If you stand on top of a dandelion and jump, the wind carries you far across the land.",
"Wenn du so etwas findest, bring es mir! Ich belohne dich auch.": "If you find something like this, bring it to me! I'll reward you too.",
"Wenn etwas umfällt, baut man es einfach noch einmal. Das ist hier das wichtigste Gesetz.": "If something falls over, you simply build it again. That's the most important law here.",
"Wer baut es, woraus?": "Who builds it, out of what?",
"Wer gerade online ist, sieht es auch. Und mit dem Kunstcode können es alle in ihr Museum holen.": "Whoever is online right now sees it too. And with the art code everyone can bring it into their museum.",
"Wer hat mich gebaut?": "Who built me?",
"Wer ist gerade da?": "Who's here right now?",
"Wer mutig ist, klettert an den Wolkenkratzern hoch. Auf manchen Dächern liegen Stadt-Medaillen.": "Brave people climb up the skyscrapers. City medals lie on some roofs.",
"Wer sind Sie?": "Who are you?",
