"Wetterballons steigen bis zu 35 Kilometer hoch. Unterwegs messen sie Temperatur, Luftdruck und Wind und funken die Werte zur Erde.": "Weather balloons rise up to 35 kilometres high. On the way they measure temperature, air pressure and wind and radio the values back to Earth.",
"Wetterfahnen gibt es seit über 2000 Jahren. Der Hahn darauf soll früh wachsam sein und die Leute an den Tagesanbruch erinnern.": "Weather vanes have existed for over 2000 years. The rooster on top is meant to be watchful early and remind people of daybreak.",
