"Wie der Bibliothekar zu seiner Brille kam": "How the Librarian Got His Glasses",
"Wie geht es dir?": "How are you?",
"Wie heisst du?": "What's your name?",
"Wie nennt man einen Cyborg im Garten? Einen Rasen-Mäher mit Gefühl.": "What do you call a cyborg in the garden? A lawnmower with feelings.",
"Wie soll ": "What should ",
"Wie soll dein ": "What should your ",
"Wie soll dein Planet heissen?": "What should your planet be called?",
"Wie sollen dich die anderen nennen? Der Name steht über deinem Cyborg und im Chat.": "What should the others call you? The name appears above your cyborg and in the chat.",
"Wie steht es um das Dorf?": "How is the village doing?",
"Wie viel Musik passt ungefähr auf eine Musik-CD?": "Roughly how much music fits on a music CD?",
