"Wiederholter Satz": "Repeated sentence",
"Wiese": "Meadow",
"Wiesen, Wälder, Kirschhaine, Flüsse. Hier wohnt ihr.": "Meadows, forests, cherry groves, rivers. This is where you live.",
"Willkommen am Magnetbahn-Ring! Der Zug schwebt seit dem 1. Januar 2000 um den Planeten und war noch nie zu spät.": "Welcome to the Maglev Ring! The train has floated around the planet since 1 January 2000 and has never been late.",
"Willkommen am grossen Lesepult!": "Welcome to the big reading desk!",
"Willkommen auf dem ": "Welcome to the ",
"Willkommen auf dem Bauklotz-Planeten! Hier ist alles aus Holz und Farbe. Und überall liegen Klötze herum.": "Welcome to the Building-Block Planet! Everything here is made of wood and paint. And there are blocks lying around everywhere.",
"Willkommen auf dem Bernstein-Mond! Hier fliesst das Harz so langsam, dass man es nur alle hundert Jahre sieht.": "Welcome to the Amber Moon! The resin flows so slowly here that you only see it every hundred years.",
"Willkommen auf dem Bildschirmschoner-Planeten! Pssst, der Planet schläft gerade. Darum sieht alles so schön aus.": "Welcome to the Screensaver Planet! Shhh, the planet is asleep right now. That's why everything looks so beautiful.",
"Willkommen auf dem Funkturm-Planeten! Hier ist immer Sendezeit.": "Welcome to the Radio Tower Planet! It's always on air here.",
"Willkommen auf dem Kompost-Planeten!": "Welcome to the Compost Planet!",
"Willkommen auf dem Laternen-Nachtmarkt! Hier geht die Sonne nie ganz unter. Es ist immer kurz nach sieben.": "Welcome to the Lantern Night Market! The sun never quite sets here. It's always just after seven.",
"Willkommen auf dem Plüsch-Planeten! Hier ist alles weich. Sogar die Felsen.": "Welcome to the Plush Planet! Everything here is soft. Even the rocks.",
"Willkommen im Kaufhaus 1999! Heute ist der 31. Dezember, und die Rolltreppen fahren extra langsam, damit niemand hetzen muss.": "Welcome to Department Store 1999! Today is 31 December, and the escalators run extra slowly so nobody has to rush.",
"Willkommen im Kokon-Netz. Schau auf die Uhr: 31.12.1999, 23:59. Gleich ist Mitternacht!": "Welcome to the Kokon Net. Look at the clock: 31.12.1999, 23:59. It's almost midnight!",
"Willkommen im Kompost-Kiosk! Alles bio, alles zirkulär.": "Welcome to the Compost Kiosk! Everything organic, everything circular.",
"Willkommen im Museum! Kunst, Fisch und Käfer aus der Welt.": "Welcome to the museum! Art, fish and beetles from all over the world.",
"Willkommen im Ranken-Rechenzentrum! Früher liefen hier die Server von halb NEMURI. Dann kamen die Pflanzen.": "Welcome to the Vine Data Centre! The servers for half of NEMURI used to run here. Then the plants came.",
"Willkommen im Rathaus! Schön, dass du hilfst.": "Welcome to the town hall! Nice of you to help.",
"Willkommen im Tierpark!": "Welcome to the animal park!",
"Willkommen im Wetterwerk! Hier wird das Wetter für das ganze Sonnensystem ausprobiert.": "Welcome to the Weather Works! Weather for the whole solar system is tried out here.",
"Willkommen in der Dino-Spielzeugfabrik! Hier läuft das Fliessband seit 1999 ohne Pause.": "Welcome to the Dino Toy Factory! The conveyor belt has run nonstop here since 1999.",
"Willkommen in der Honigwaben-Fabrik! Hier summt es den ganzen Tag. Keine Sorge, unsere Bienen sind aus Plüsch und Plastik.": "Welcome to the Honeycomb Factory! It buzzes here all day long. Don't worry, our bees are made of plush and plastic.",
"Willkommen in der Leuchtquallen-Tiefsee! Hier unten ist es immer ein bisschen dämmrig. Darum leuchten alle selbst.": "Welcome to the Glowing Jellyfish Deep Sea! It's always a bit dim down here. That's why everyone glows by themselves.",
"Willkommen in der Metro-Stadt! Hier schläft niemand – und wenn doch, dann nach dem Jazz-Festival.": "Welcome to Metro City! Nobody sleeps here – and if they do, then after the jazz festival.",
"Willkommen in der Neon-Arkade! Hier wird nie ausgeschaltet. Es ist immer kurz vor Mitternacht.": "Welcome to the Neon Arcade! Nothing is ever switched off here. It's always just before midnight.",
"Willkommen in der Spielhalle! Ich bin Tilly.": "Welcome to the arcade! I'm Tilly.",
"Willkommen!": "Welcome!",
