"Winkerkrabben winken mit einer riesigen Schere, um Weibchen zu beeindrucken und Rivalen zu vertreiben. Die Schere kann halb so schwer sein wie die ganze Krabbe.": "Fiddler crabs wave a giant claw to impress females and drive off rivals. The claw can be half as heavy as the whole crab.",
