"Wird es wärmer, dehnt sie sich aus und steigt nach oben. Wird es kälter, zieht sie sich zusammen.": "When it gets warmer, it expands and rises. When it gets colder, it contracts.",
"Wird schnell wütend, beruhigt sich aber auch schnell.": "Gets angry quickly, but calms down quickly too.",
