"Wolle": "Wool",
"Wolle kommt meist vom Schaf. Ein Schaf gibt pro Jahr etwa vier Kilogramm Wolle – genug für mehrere Pullover.": "Wool usually comes from sheep. A sheep gives about four kilograms of wool a year – enough for several jumpers.",
"Wollfaden": "Woollen thread",
"Wollgarage": "Wool garage",
"Wollhaarmammuts lebten während der Eiszeit und starben erst vor etwa 4000 Jahren endgültig aus – da gab es schon die Pyramiden! Mit ihren gebogenen Stosszähnen schoben sie Schnee beiseite, um an Gras zu kommen. Heute tauen im Permafrost immer mehr Mammut-Reste auf.": "Woolly mammoths lived during the ice age and only died out for good about 4000 years ago – the pyramids already existed then! With their curved tusks they pushed snow aside to get to the grass. Today more and more mammoth remains are thawing out of the permafrost.",
"Wolli": "Woolly",
"Wollknäuel": "Ball of wool",
"Wollmammuts lebten bis vor etwa 4000 Jahren auf einer Insel im Nordpolarmeer. Im Permafrost blieben manche so gut erhalten, dass man ihr Fell noch sieht.": "Woolly mammoths lived on an island in the Arctic Ocean until about 4000 years ago. Some were so well preserved in the permafrost that you can still see their fur.",
"Wollschaf": "Woolly sheep",
"Wollschal": "Woollen scarf",
"Wollschweber": "Bee fly",
"Wollschweber stehen beim Trinken in der Luft still, wie kleine Kolibris. Ihr Rüssel ist so lang wie ihr Körper.": "Bee flies hover in the air while drinking, like little hummingbirds. Their proboscis is as long as their body.",
"Wollwal": "Wool whale",
