"Wüstenheuschrecke": "Desert locust",
"Wüstenheuschrecken ändern ihr Verhalten und sogar ihre Farbe, wenn es eng wird: Aus Einzelgängern werden riesige Schwärme.": "Desert locusts change their behaviour and even their colour when it gets crowded: loners turn into huge swarms.",
"Wüstenkäfer laufen auf langen Beinen, damit ihr Körper weit über dem heissen Sand bleibt. Manche sammeln Nebeltropfen auf dem Rücken zum Trinken.": "Desert beetles walk on long legs so their body stays high above the hot sand. Some collect fog droplets on their back to drink.",
"Wüstenkärpfling": "Desert pupfish",
"Wüstenkärpflinge halten Wassertemperaturen über 40 °C und sehr salziges Wasser aus. Einige Arten leben in einer einzigen, winzigen Quelle.": "Desert pupfish survive water temperatures over 40 °C and very salty water. Some species live in a single tiny spring.",
"Wüstenrose": "Desert rose",
"Wüstenspringmaus": "Jerboa",
"Wüstenspringmäuse hüpfen auf zwei langen Hinterbeinen – wie kleine Kängurus – bis zu drei Meter weit.": "Jerboas hop on two long hind legs – like little kangaroos – up to three metres far.",
