"Zahnspange": "Braces",
"Zander sehen im Trüben besonders gut: Eine reflektierende Schicht hinter der Netzhaut verstärkt das Licht, wie bei Katzen.": "Zander see especially well in murky water: a reflective layer behind the retina boosts the light, like in cats.",
