"Zifferschrift": "Digit lettering",
"Zikaden erzeugen ihren Gesang mit Trommelorganen am Hinterleib. Manche Arten sind so laut wie ein Rasenmäher.": "Cicadas make their song with drum organs on their abdomen. Some species are as loud as a lawnmower.",
"Zikaden gehören zu den lautesten Insekten. Ihr Gesang entsteht in trommelartigen Organen am Hinterleib und kann über 100 Dezibel laut sein.": "Cicadas are among the loudest insects. Their song comes from drum-like organs on their abdomen and can be over 100 decibels loud.",
"Zikaden machen ihr Geräusch mit einer Trommelhaut am Bauch. Manche sind so laut wie ein Rasenmäher.": "Cicadas make their noise with a drum skin on their belly. Some are as loud as a lawnmower.",
"Zimmerpalme": "Parlour palm",
"Zimmerpflanze": "Houseplant",
"Zipfel": "Tip",
"Zirrus": "Cirrus",
"Zitrone": "Lemon",
"Zitronenfalter": "Brimstone butterfly",
"Zitronenfalter sind oft die ersten Schmetterlinge im Frühling, weil sie als erwachsene Falter draussen überwintern. Ein körpereigenes Frostschutzmittel lässt sie sogar Minusgrade überstehen. Mit bis zu einem Jahr Lebenszeit sind sie echte Falter-Senioren.": "Brimstone butterflies are often the first butterflies in spring because they spend the winter outside as adults. A natural antifreeze lets them survive even sub-zero temperatures. Living up to a year, they are real butterfly seniors.",
"Zitronenfalter überwintern ohne Versteck, frei an Zweigen. Ein Frostschutzmittel in ihrem Körper verhindert, dass sie erfrieren.": "Brimstone butterflies overwinter without a hiding place, out in the open on twigs. An antifreeze in their body stops them from freezing.",
"Zitteraal": "Electric eel",
"Zitteraale erzeugen Stromstösse von bis zu 800 Volt. Eigentlich sind sie keine Aale, sondern Verwandte der Welse.": "Electric eels produce electric shocks of up to 800 volts. They aren't actually eels but relatives of catfish.",
"Zitteraale erzeugen mit Muskelzellen bis zu 600 Volt. Sie nutzen schwache Stromstösse auch zum Orientieren im trüben Wasser.": "Electric eels produce up to 600 volts with muscle cells. They also use weak electric pulses to find their way in murky water.",
