"Was ein Teil in der Welt tut, steht im blauen Feld. Gebt jedem Teil trotzdem eure eigene Deutung: Was bedeutet diese Fähigkeit, wem nützt sie? Mindestens vier Teile, eines davon dient einer anderen Art.": "What a part does in the world is shown in the blue box. Still, give every part your own meaning: what does this ability mean, who does it help? At least four parts, one of which serves another species.",
